import http.server, socketserver, sys, time, gzip, json
class H(http.server.BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    def log_message(self,*a): 
        sys.stderr.write("REQ %s %s %s headers=%s\n"%(self.command,self.path,self.request_version,dict(self.headers)))
    def do_GET(self): self.handle_all()
    def do_POST(self): self.handle_all()
    def do_PUT(self): self.handle_all()
    def do_DELETE(self): self.handle_all()
    def do_HEAD(self): self.handle_all()
    def do_PATCH(self): self.handle_all()
    def do_OPTIONS(self): self.handle_all()
    def handle_all(self):
        length=int(self.headers.get('Content-Length') or 0)
        body=self.rfile.read(length) if length else b''
        if body: sys.stderr.write("BODY %r\n"%body)
        if self.path=='/redirect':
            self.send_response(302); self.send_header('Location','/'); self.send_header('Content-Length','0'); self.end_headers(); return
        if self.path=='/redirect-loop':
            self.send_response(302); self.send_header('Location','/redirect-loop'); self.send_header('Content-Length','0'); self.end_headers(); return
        if self.path=='/slow':
            time.sleep(0.5)
        if self.path=='/notfound':
            data=b'not found'; self.send_response(404); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path=='/error':
            data=b'err'; self.send_response(500); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path=='/gzip':
            data=gzip.compress(b'hello gzip world'*10); self.send_response(200); self.send_header('Content-Encoding','gzip'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path=='/chunked':
            data=b'chunked-hello'; self.send_response(200); self.send_header('Transfer-Encoding','chunked'); self.end_headers(); self.wfile.write(b'%x\r\n%s\r\n0\r\n\r\n'%(len(data),data)); return
        if self.path.startswith('/echo'):
            data=json.dumps({"method":self.command,"path":self.path,"headers":dict(self.headers),"body":body.decode('utf-8','replace')}).encode()
            self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        data=b'Hello World'
        self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.send_header('X-Custom','yes'); self.end_headers(); self.wfile.write(data)
class ThreadingHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads=True
port=int(sys.argv[1]) if len(sys.argv)>1 else 18080
ThreadingHTTPServer(('127.0.0.1',port),H).serve_forever()
