use std::time::{Duration, SystemTime, UNIX_EPOCH};

pub fn now_unix_secs() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0)
}

// civil date conversion from days since epoch (Howard Hinnant's algorithm)
pub fn format_utc_amz(secs: u64) -> String {
    let days = (secs / 86400) as i64;
    let rem = secs % 86400;
    let (hh, mm, ss) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };
    format!("{:04}{:02}{:02}T{:02}{:02}{:02}Z", year, m, d, hh, mm, ss)
}
pub fn format_utc_date(secs: u64) -> String {
    let s = format_utc_amz(secs);
    s[..8].to_string()
}

pub struct Rng(u128);
impl Rng {
    pub fn new() -> Self {
        let mut seed: u128 = 0;
        if let Ok(bytes) = std::fs::read("/dev/urandom") { let _ = bytes; }
        // getrandom via /dev/urandom file handle properly:
        use std::io::Read;
        let mut buf = [0u8; 16];
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") { let _ = f.read_exact(&mut buf); }
        seed = u128::from_le_bytes(buf);
        if seed == 0 {
            seed = (SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0)) ^ ((std::process::id() as u128) << 64) ^ 0x9e3779b97f4a7c15;
        }
        Rng(seed)
    }
    pub fn next_u64(&mut self) -> u64 {
        // xorshift128+
        let mut x = self.0;
        let mut y = (x >> 64) as u64;
        let x1 = x as u64;
        let result = x1.wrapping_add(y);
        let mut xx = y ^ x1;
        xx ^= xx << 23;
        xx ^= xx >> 17;
        xx ^= y ^ (y >> 26);
        self.0 = ((y as u128) << 64) | (xx as u128);
        let _ = result;
        xx.wrapping_add(y)
    }
    pub fn next_u128(&mut self) -> u128 { ((self.next_u64() as u128) << 64) | self.next_u64() as u128 }
    pub fn below(&mut self, n: usize) -> usize {
        if n == 0 { return 0; }
        (self.next_u64() % (n as u64)) as usize
    }
    pub fn below_u32(&mut self, n: u32) -> u32 {
        if n == 0 { return 0; }
        (self.next_u64() % (n as u64)) as u32
    }
}

pub fn f64_display(v: f64) -> String {
    // Rust Display for f64
    format!("{}", v)
}

pub fn json_f64(v: f64) -> String {
    if !v.is_finite() { return "null".to_string(); }
    let mut buf = ryu::Buffer::new();
    buf.format_finite(v).to_string()
}
pub fn json_f64_opt(v: f64) -> String { json_f64(v) }

pub fn gettid() -> u64 {
    unsafe { libc::syscall(libc::SYS_gettid) as u64 }
}

pub fn escape_byte_string(bytes: &[u8]) -> String {
    // Mimic Rust debug byte string b"..." as produced for hyper/bytes debug output
    let mut out = String::new();
    out.push_str("b\"");
    for &b in bytes {
        match b {
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'\t' => out.push_str("\\t"),
            b'\\' => out.push_str("\\\\"),
            b'"' => out.push_str("\\\""),
            0 => out.push_str("\\0"),
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02x}", b)),
        }
    }
    out.push('"');
    out
}

pub fn escape_header_value_debug(bytes: &[u8]) -> String {
    // http HeaderValue Debug: quoted string, escapes as \xNN for non-printable/non-ascii
    let mut out = String::new();
    out.push('"');
    for &b in bytes {
        match b {
            b'\t' => out.push('\t'),
            b'\\' => out.push_str("\\\\"),
            b'"' => out.push_str("\\\""),
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02x}", b)),
        }
    }
    out.push('"');
    out
}

pub fn duration_from_secs_f64_panic(v: f64) -> Duration {
    Duration::from_secs_f64(v)
}
