type SSL_CTX = c_void;
type SSL = c_void;
type BIO = c_void;
type X509 = c_void;
type X509_STORE = c_void;

extern "C" {
    fn TLS_client_method() -> *const c_void;
    fn SSL_CTX_new(meth: *const c_void) -> *mut SSL_CTX;
    fn SSL_CTX_free(ctx: *mut SSL_CTX);
    fn SSL_CTX_set_verify(ctx: *mut SSL_CTX, mode: i32, cb: *const c_void);
