    fn ERR_get_error() -> u64;
    fn ERR_error_string_n(e: u64, buf: *mut u8, len: usize);
    fn SSL_CTX_use_certificate_chain_file(ctx: *mut SSL_CTX, file: *const i8) -> i32;
    fn SSL_CTX_use_PrivateKey_file(ctx: *mut SSL_CTX, file: *const i8, ty: i32) -> i32;
    fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
    fn SSL_free(ssl: *mut SSL);
    fn BIO_new_socket(fd: i32, close_flag: i32) -> *mut BIO;
    fn SSL_set_bio(ssl: *mut SSL, rbio: *mut BIO, wbio: *mut BIO);
    fn SSL_ctrl(ssl: *mut SSL, cmd: i32, larg: i64, parg: *mut c_void) -> i64;
    fn SSL_set_alpn_protos(ssl: *mut SSL, protos: *const u8, len: u32) -> i32;
    fn SSL_get0_alpn_selected(ssl: *const SSL, data: *mut *const u8, len: *mut u32);
    fn SSL_connect(ssl: *mut SSL) -> i32;
    fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: i32) -> i32;
    fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: i32) -> i32;
    fn SSL_get_error(ssl: *const SSL, ret: i32) -> i32;
    fn SSL_get_verify_result(ssl: *const SSL) -> i64;
    fn X509_verify_cert_error_string(n: i64) -> *const i8;
    fn SSL_shutdown(ssl: *mut SSL) -> i32;
}

const SSL_VERIFY_NONE: i32 = 0;
const SSL_VERIFY_PEER: i32 = 1;
const BIO_NOCLOSE: i32 = 0;
const SSL_CTRL_SET_TLSEXT_HOSTNAME: i32 = 55;

#[derive(Clone, Debug)]
pub struct TlsConfig {
    pub insecure: bool,
    pub cacert_content: Option<Vec<u8>>,
    pub cert: Option<PathBuf>,
    pub key: Option<PathBuf>,
}

fn last_ssl_error_string() -> String {
    unsafe {
        let e = ERR_get_error();
        if e == 0 { return String::new(); }
        let mut buf = vec![0u8; 256];
        ERR_error_string_n(e, buf.as_mut_ptr(), buf.len());
        let s = String::from_utf8_lossy(&buf);
        s.trim_end_matches('\0').to_string()
    }
}

pub struct TlsStream {
    ssl: *mut SSL,
    ctx: *mut SSL_CTX,
    stream: TcpStream,
    pub alpn_h2: bool,
}
unsafe impl Send for TlsStream {}

impl TlsStream {
    pub fn connect(cfg: &TlsConfig, stream: TcpStream, server_name: &str, want_h2: bool) -> Result<TlsStream, String> {
        unsafe {
            let ctx = SSL_CTX_new(TLS_client_method());
            if ctx.is_null() { return Err("tls error".to_string()); }
            SSL_CTX_set_verify(ctx, if cfg.insecure { SSL_VERIFY_NONE } else { SSL_VERIFY_PEER }, std::ptr::null());
            if !cfg.insecure {
                SSL_CTX_set_default_verify_paths(ctx);
                if let Some(content) = &cfg.cacert_content {
                    let store = SSL_CTX_get_cert_store(ctx);
                    if !store.is_null() && !content.is_empty() {
                        let bio = BIO_new_mem_buf(content.as_ptr() as *const c_void, content.len() as i32);
                        if !bio.is_null() {
                            loop {
                                let mut x: *mut X509 = std::ptr::null_mut();
                                let cert = PEM_read_bio_X509(bio, &mut x, std::ptr::null(), std::ptr::null_mut());
                                if cert.is_null() { break; }
                                X509_STORE_add_cert(store, cert);
                                X509_free(cert);
                            }
                            BIO_free(bio);
                        }
                        ERR_clear_error();
                    }
                }
            }
            if let (Some(cert), Some(key)) = (&cfg.cert, &cfg.key) {
                if let (Ok(cfile), Ok(kfile)) = (CString::new(cert.to_string_lossy().as_bytes()), CString::new(key.to_string_lossy().as_bytes())) {
                    SSL_CTX_use_certificate_chain_file(ctx, cfile.as_ptr());
                    SSL_CTX_use_PrivateKey_file(ctx, kfile.as_ptr(), 1);
                }
                ERR_clear_error();
            }
            let ssl = SSL_new(ctx);
            if ssl.is_null() { SSL_CTX_free(ctx); return Err("tls error".to_string()); }
            let bio = BIO_new_socket(stream.as_raw_fd(), BIO_NOCLOSE);
            SSL_set_bio(ssl, bio, bio);
            // SNI only for non-IP names
            if server_name.parse::<std::net::IpAddr>().is_err() && !server_name.is_empty() {
                if let Ok(cname) = CString::new(server_name) {
                    SSL_ctrl(ssl, SSL_CTRL_SET_TLSEXT_HOSTNAME, 0, cname.as_ptr() as *mut c_void);
                }
            }
            let protos: &[u8] = if want_h2 { &[2, b'h', b'2'] } else { &[8, b'h', b't', b't', b'p', b'/', b'1', b'.', b'1'] };
            SSL_set_alpn_protos(ssl, protos.as_ptr(), protos.len() as u32);
            let ret = SSL_connect(ssl);
            if ret != 1 {
                let verify = SSL_get_verify_result(ssl);
                let errkind = SSL_get_error(ssl, ret);
                let mut msg = last_ssl_error_string();
                // drain additional errors
                while { let e = ERR_get_error(); e != 0 } { let _ = e; }
                if verify != 0 {
                    let vstr = {
                        let p = X509_verify_cert_error_string(verify);
                        if p.is_null() { String::new() } else { std::ffi::CStr::from_ptr(p).to_string_lossy().to_string() }
                    };
                    msg = map_verify_error(&vstr);
                    SSL_free(ssl); SSL_CTX_free(ctx);
                    return Err(msg);
                }
                SSL_free(ssl); SSL_CTX_free(ctx);
                if errkind == 5 || errkind == 1 && msg.contains("unexpected eof") || msg.to_lowercase().contains("eof") {
                    return Err("tls handshake eof".to_string());
                }
                if msg.is_empty() { msg = "tls handshake eof".to_string(); }
                // OpenSSL errors often have prefixes; present lower-case-ish message
                return Err(msg);
            }
            let mut data: *const u8 = std::ptr::null();
            let mut len: u32 = 0;
            SSL_get0_alpn_selected(ssl, &mut data, &mut len);
            let alpn_h2 = if !data.is_null() && len > 0 {
                let sl = std::slice::from_raw_parts(data, len as usize);
                sl == b"h2"
            } else { false };
            Ok(TlsStream { ssl, ctx, stream, alpn_h2 })
        }
    }
    pub fn set_read_timeout(&self, d: Option<std::time::Duration>) -> io::Result<()> { self.stream.set_read_timeout(d) }
    pub fn set_write_timeout(&self, d: Option<std::time::Duration>) -> io::Result<()> { self.stream.set_write_timeout(d) }
    pub fn inner(&self) -> &TcpStream { &self.stream }
}

fn map_verify_error(vstr: &str) -> String {
    let low = vstr.to_lowercase();
    if low.contains("self-signed") || low.contains("self signed") || low.contains("unable to get local issuer") || low.contains("unable to verify") {
        "invalid peer certificate: UnknownIssuer".to_string()
    } else if low.contains("expired") {
        "invalid peer certificate: Expired".to_string()
    } else if low.contains("invalid ca") || low.contains("ca cert") || low.contains("invalid purpose") {
        "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string()
    } else {
        format!("invalid peer certificate: {}", vstr)
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() { return Ok(0); }
        unsafe {
            let ret = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, buf.len().min(i32::MAX as usize) as i32);
            if ret > 0 { Ok(ret as usize) } else {
                let e = SSL_get_error(self.ssl, ret);
                // SSL_ERROR_WANT_READ = 2, WANT_WRITE=3, ZERO_RETURN=6, SYSCALL=5
                if e == 6 { Ok(0) } else if e == 2 || e == 3 {
                    Err(io::Error::new(io::ErrorKind::WouldBlock, "ssl want read"))
                } else {
                    let _ = last_ssl_error_string(); while ERR_get_error() != 0 {}
                    Err(io::Error::new(io::ErrorKind::ConnectionAborted, "tls read error"))
                }
            }
        }
    }
}
impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        unsafe {
            let ret = SSL_write(self.ssl, buf.as_ptr() as *const c_void, buf.len().min(i32::MAX as usize) as i32);
            if ret > 0 { Ok(ret as usize) } else {
                let e = SSL_get_error(self.ssl, ret);
                if e == 2 || e == 3 { Err(io::Error::new(io::ErrorKind::WouldBlock, "ssl want write")) } else { let _ = last_ssl_error_string(); while ERR_get_error() != 0 {} Err(io::Error::new(io::ErrorKind::ConnectionAborted, "tls write error")) }
            }
        }
    }
    fn flush(&mut self) -> io::Result<()> { Ok(()) }
}
impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe {
            if !self.ssl.is_null() { SSL_shutdown(self.ssl); SSL_free(self.ssl); }
            if !self.ctx.is_null() { SSL_CTX_free(self.ctx); }
        }
    }
}
