pub fn store(path: &str, rows: &[DbRow], run: i64) -> Result<(), String> {
    let cpath = CString::new(path).map_err(|_| format!("unable to open database file: {}", path))?;
    unsafe {
        let mut db: *mut DB = std::ptr::null_mut();
        let rc = sqlite3_open(cpath.as_ptr(), &mut db);
        if rc != SQLITE_OK || db.is_null() {
            let msg = if !db.is_null() { let m = errmsg(db); sqlite3_close(db); m } else { "unable to open database file".to_string() };
            if msg.contains("unable to open") {
                return Err(format!("unable to open database file: {}", path));
            }
            return Err(msg);
        }
        let create = "CREATE TABLE IF NOT EXISTS oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )";
        let csql = CString::new(create).unwrap();
        let mut err_ptr: *mut i8 = std::ptr::null_mut();
        let rc = sqlite3_exec(db, csql.as_ptr(), std::ptr::null(), std::ptr::null_mut(), &mut err_ptr);
