            sqlite3_close(db);
            return Err(msg);
        }
        // transaction
        let begin = CString::new("BEGIN").unwrap();
        sqlite3_exec(db, begin.as_ptr(), std::ptr::null(), std::ptr::null_mut(), std::ptr::null_mut());
        let insert = "INSERT INTO oha (url, start, start_latency_correction, end, duration, status, len_bytes, run) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)";
        let cstmt = CString::new(insert).unwrap();
