        let rc = sqlite3_prepare_v2(db, cstmt.as_ptr(), -1, &mut stmt, std::ptr::null_mut());
        if rc != SQLITE_OK { let m = errmsg(db); sqlite3_close(db); return Err(m); }
        for r in rows {
            let curl = CString::new(r.url.as_str()).unwrap_or_else(|_| CString::new("").unwrap());
            sqlite3_bind_text(stmt, 1, curl.as_ptr(), curl.as_bytes().len() as i32, SQLITE_TRANSIENT);
            sqlite3_bind_double(stmt, 2, r.start);
            match r.start_correction { Some(v) => { sqlite3_bind_double(stmt, 3, v); }, None => { sqlite3_bind_null(stmt, 3); } }
            sqlite3_bind_double(stmt, 4, r.end);
            sqlite3_bind_double(stmt, 5, r.duration);
            sqlite3_bind_int64(stmt, 6, r.status);
            sqlite3_bind_int64(stmt, 7, r.len_bytes);
            sqlite3_bind_int64(stmt, 8, run);
            let src = sqlite3_step(stmt);
            if src != SQLITE_DONE {
                let m = errmsg(db);
                sqlite3_finalize(stmt);
                let rb = CString::new("ROLLBACK").unwrap(); sqlite3_exec(db, rb.as_ptr(), std::ptr::null(), std::ptr::null_mut(), std::ptr::null_mut());
                sqlite3_close(db);
                return Err(m);
            }
