            extern "C" { fn sqlite3_reset(stmt: *mut c_void) -> i32; fn sqlite3_clear_bindings(stmt: *mut c_void) -> i32; }
            sqlite3_reset(stmt); sqlite3_clear_bindings(stmt);
        }
        sqlite3_finalize(stmt);
        let commit = CString::new("COMMIT").unwrap();
        sqlite3_exec(db, commit.as_ptr(), std::ptr::null(), std::ptr::null_mut(), std::ptr::null_mut());
        sqlite3_close(db);
        Ok(())
    }
}
