use crate::util::Rng;
use regex_syntax::hir::{Class, Hir, HirKind};
use std::sync::Mutex;

pub struct RandRegex {
    hir: Hir,
    max_repeat: u32,
    rng: Mutex<Rng>,
}

impl RandRegex {
    pub fn new(pattern: &str, max_repeat: u32) -> Result<Self, String> {
        let hir = regex_syntax::Parser::new().parse(pattern).map_err(|e| e.to_string())?;
        Ok(RandRegex { hir, max_repeat, rng: Mutex::new(Rng::new()) })
    }
    pub fn generate(&self) -> String {
        let mut rng = self.rng.lock().unwrap();
        let mut out = String::new();
        gen_hir(&self.hir, &mut rng, self.max_repeat, &mut out);
        out
    }
}

fn choose_count(rng: &mut Rng, min: u32, max: Option<u32>, max_repeat: u32) -> u32 {
    let hi = match max { Some(m) => m, None => min.saturating_add(max_repeat) };
    if hi <= min { return min; }
    min + rng.below_u32(hi - min + 1)
}

fn gen_hir(hir: &Hir, rng: &mut Rng, max_repeat: u32, out: &mut String) {
    match hir.kind() {
        HirKind::Empty => {}
        HirKind::Literal(lit) => {
            if let Ok(s) = std::str::from_utf8(&lit.0) { out.push_str(s); } else { for b in lit.0.iter() { out.push(*b as char); } }
        }
        HirKind::Class(class) => {
            let ch = pick_class_char(class, rng);
            out.push(ch);
        }
        HirKind::Repetition(rep) => {
            let n = choose_count(rng, rep.min, rep.max, max_repeat);
            for _ in 0..n { gen_hir(&rep.sub, rng, max_repeat, out); }
        }
        HirKind::Capture(cap) => { gen_hir(&cap.sub, rng, max_repeat, out); }
        HirKind::Concat(list) => { for h in list { gen_hir(h, rng, max_repeat, out); } }
        HirKind::Alternation(list) => {
            if !list.is_empty() { let idx = rng.below(list.len()); gen_hir(&list[idx], rng, max_repeat, out); }
        }
        HirKind::Look(_) => {}
    }
}

fn pick_class_char(class: &Class, rng: &mut Rng) -> char {
    match class {
        Class::Unicode(ranges) => {
            let total: u64 = ranges.ranges().iter().map(|r| (r.end() as u64 - r.start() as u64) + 1).sum();
            if total == 0 { return 'a'; }
            let mut idx = (rng.next_u64() % total) as u64;
            for r in ranges.ranges() {
                let len = (r.end() as u64 - r.start() as u64) + 1;
                if idx < len { return char::from_u32(r.start() + idx as u32).unwrap_or('a'); }
                idx -= len;
            }
            'a'
        }
        Class::Bytes(ranges) => {
            let total: u64 = ranges.ranges().iter().map(|r| (r.end() as u64 - r.start() as u64) + 1).sum();
            if total == 0 { return 'a'; }
            let mut idx = rng.next_u64() % total;
            for r in ranges.ranges() {
                let len = (r.end() as u64 - r.start() as u64) + 1;
                if idx < len { return (r.start() + idx as u8) as char; }
                idx -= len;
            }
            'a'
        }
    }
}
