use crate::rand_regex::RandRegex;
use crate::util::Rng;
use std::sync::Mutex;
use url::Url;

pub enum UrlGeneratorKind {
    Static(Url),
    FromFile(Vec<Url>),
    RandRegex(RandRegex),
}

pub struct UrlGenerator {
    kind: UrlGeneratorKind,
    rng: Mutex<Rng>,
}

impl UrlGenerator {
    pub fn new_static(url_str: &str) -> Result<Self, String> {
        let url = Url::parse(url_str).map_err(|e| e.to_string())?;
        Ok(UrlGenerator { kind: UrlGeneratorKind::Static(url), rng: Mutex::new(Rng::new()) })
    }

    pub fn new_from_file(path: &str) -> Result<Self, String> {
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        let mut urls: Vec<Url> = Vec::new();
        for line in content.lines() {
            if line.is_empty() { continue; }
            let url = Url::parse(line).map_err(|e| e.to_string())?;
            urls.push(url);
        }
        assert!(!urls.is_empty());
        Ok(UrlGenerator { kind: UrlGeneratorKind::FromFile(urls), rng: Mutex::new(Rng::new()) })
    }

    pub fn new_rand_regex(url_str: &str, max_repeat: u32) -> Result<Self, String> {
        let pattern = url_str.replace('.', "\\.");
        let gen = RandRegex::new(&pattern, max_repeat)?;
        // Validate one generated URL as the original does at construction time.
        let generated = gen.generate();
        let _url = Url::parse(&generated).map_err(|e| format!("{}, generated url: {}", e, generated))?;
        Ok(UrlGenerator { kind: UrlGeneratorKind::RandRegex(gen), rng: Mutex::new(Rng::new()) })
    }

    pub fn generate(&self) -> Result<Url, String> {
        match &self.kind {
            UrlGeneratorKind::Static(url) => Ok(url.clone()),
            UrlGeneratorKind::FromFile(urls) => {
                let idx = { let mut rng = self.rng.lock().unwrap(); rng.below(urls.len()) };
                Ok(urls[idx].clone())
            }
            UrlGeneratorKind::RandRegex(gen) => {
                let generated = gen.generate();
                Url::parse(&generated).map_err(|e| format!("{}, generated url: {}", e, generated))
            }
        }
    }
}
