use crate::model::SuccessResult;
use crate::util;
use std::collections::BTreeMap;
use std::time::Duration;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum TimeUnitKind { Ns, Us, Ms, S, M, H }
impl TimeUnitKind {
    pub fn label(&self) -> &'static str {
        match self { TimeUnitKind::Ns => "ns", TimeUnitKind::Us => "us", TimeUnitKind::Ms => "ms", TimeUnitKind::S => "sec", TimeUnitKind::M => "min", TimeUnitKind::H => "hr" }
    }
    pub fn convert(&self, secs: f64) -> f64 {
        match self { TimeUnitKind::Ns => secs * 1e9, TimeUnitKind::Us => secs * 1e6, TimeUnitKind::Ms => secs * 1e3, TimeUnitKind::S => secs, TimeUnitKind::M => secs / 60.0, TimeUnitKind::H => secs / 3600.0 }
    }
    pub fn from_slowest(slowest: f64) -> Self {
        if slowest >= 3600.0 { TimeUnitKind::H } else if slowest >= 60.0 { TimeUnitKind::M } else if slowest >= 1.0 { TimeUnitKind::S } else if slowest >= 0.001 { TimeUnitKind::Ms } else if slowest >= 0.000001 { TimeUnitKind::Us } else { TimeUnitKind::Ns }
    }
    pub fn parse(s: &str) -> Option<Self> {
        match s { "ns" => Some(TimeUnitKind::Ns), "us" => Some(TimeUnitKind::Us), "ms" => Some(TimeUnitKind::Ms), "s" => Some(TimeUnitKind::S), "m" => Some(TimeUnitKind::M), "h" => Some(TimeUnitKind::H), _ => None }
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum StyleMode { Plain, Color, ColorEnvNoColor }

pub struct Printer {
    pub mode: StyleMode,
    pub time_unit: Option<TimeUnitKind>,
    pub stats_success_breakdown: bool,
}

pub fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return f64::NAN; }
    let idx = ((p / 100.0) * sorted.len() as f64) as usize;
    let idx = idx.min(sorted.len() - 1);
    sorted[idx]
}

pub fn percentiles_map(sorted: &[f64]) -> Vec<(String, f64)> {
    let ps: [( &str, f64); 9] = [("p10",10.0),("p25",25.0),("p50",50.0),("p75",75.0),("p90",90.0),("p95",95.0),("p99",99.0),("p99.9",99.9),("p99.99",99.99)];
    ps.iter().map(|(k,p)| (k.to_string(), percentile(sorted, *p))).collect()
}

pub struct Histogram { pub labels: Vec<f64>, pub counts: Vec<usize> }
pub fn histogram(durations: &[f64]) -> Histogram {
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let step = (slowest - fastest) / 10.0;
    let labels: Vec<f64> = (0..=10).map(|i| fastest + step * i as f64).collect();
    let mut counts = vec![0usize; 11];
    for &d in durations {
        let ratio = if slowest > fastest { (d - fastest) / (slowest - fastest) } else { f64::NAN };
        let mut idx = (ratio * 10.0).ceil() as usize;
        if d == fastest { idx = 0; }
        if idx > 10 { idx = 10; }
        counts[idx] += 1;
    }
    Histogram { labels, counts }
}

pub fn format_bytes(v: f64) -> String {
    if !v.is_finite() { return format!("{}", v); }
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut size = v;
    let mut idx = 0usize;
    while size >= 1024.0 && idx < UNITS.len() - 1 { size /= 1024.0; idx += 1; }
    if idx == 0 { format!("{} B", size as i64) } else { format!("{:.2} {}", size, UNITS[idx]) }
}

pub struct Stats {
    pub success_rate: f64,
    pub total_secs: f64,
    pub slowest: f64,
    pub fastest: f64,
    pub average: f64,
    pub requests_per_sec: f64,
    pub total_data: usize,
    pub size_per_request: Option<usize>,
    pub size_per_sec: f64,
}

pub fn compute_stats(successes: &[SuccessResult], n_errors: usize, total: Duration) -> Stats {
    let mut durations: Vec<f64> = successes.iter().map(|r| r.duration.as_secs_f64()).collect();
    durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
    let total_secs = total.as_secs_f64();
    let total_attempts = successes.len() + n_errors;
    let success_rate = successes.len() as f64 / total_attempts as f64;
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let average = if durations.is_empty() { f64::NAN } else { durations.iter().sum::<f64>() / durations.len() as f64 };
    let requests_per_sec = total_attempts as f64 / total_secs;
    let total_data: usize = successes.iter().map(|r| r.len_bytes).sum();
    let size_per_request = if successes.is_empty() { None } else { Some(total_data / successes.len()) };
    let size_per_sec = total_data as f64 / total_secs;
    Stats { success_rate, total_secs, slowest, fastest, average, requests_per_sec, total_data, size_per_request, size_per_sec }
}

pub fn rps_samples(successes: &[SuccessResult], start: std::time::Instant) -> Vec<f64> {
    let mut by_end: Vec<&SuccessResult> = successes.iter().collect();
    by_end.sort_by_key(|r| r.end);
    let mut samples = Vec::new();
    let mut prev = start;
    for r in by_end {
        let dt = r.end.duration_since(prev).as_secs_f64();
        samples.push(1.0 / dt);
        prev = r.end;
    }
    samples.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    samples
}

pub fn mean_std(vals: &[f64]) -> (f64, f64, f64, f64) {
    if vals.is_empty() { return (f64::NAN, f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
    let std = if vals.len() <= 1 { f64::NAN } else {
        let var = vals.iter().map(|v| (v-mean)*(v-mean)).sum::<f64>() / (vals.len() - 1) as f64;
        var.sqrt()
    };
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (mean, std, min, max)
}

impl Printer {
    fn fg(&self, code: u8) -> String {
        match self.mode { StyleMode::Color => format!("\x1b[38;5;{}m", code), StyleMode::ColorEnvNoColor => "\x1b[m".to_string(), StyleMode::Plain => String::new() }
    }
    fn reset_fg(&self) -> String {
        match self.mode { StyleMode::Color => "\x1b[39m".to_string(), StyleMode::ColorEnvNoColor => "\x1b[m".to_string(), StyleMode::Plain => String::new() }
    }
    fn heading(&self, text: &str) -> String {
        match self.mode { StyleMode::Plain => text.to_string(), _ => format!("\x1b[1m\x1b[4m{}\x1b[0m", text) }
    }
    fn fmt_dur(&self, secs: f64, unit: TimeUnitKind) -> String { format!("{:.4} {}", unit.convert(secs), unit.label()) }
    fn fmt_dur3(&self, secs: f64, unit: TimeUnitKind) -> String { format!("{:.3}", unit.convert(secs)) }

    fn histogram_text(&self, durations: &[f64], unit: TimeUnitKind) -> String {
        let hist = histogram(durations);
        let labels_str: Vec<String> = hist.labels.iter().map(|v| self.fmt_dur3(*v, unit)).collect();
        let mut label_width = labels_str.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        if durations.is_empty() { label_width = label_width.max(5); }
        let max_count_bracket_len = hist.counts.iter().max().map(|m| format!("[{}]", m).len()).unwrap_or(3);
        let max_count = *hist.counts.iter().max().unwrap_or(&0);
        let mut out = String::new();
        for (i, cnt) in hist.counts.iter().enumerate() {
            let label = &labels_str[i];
            let bracket = format!("[{}]", cnt);
            let bar_len = if max_count == 0 { 0 } else { ((*cnt as f64 / max_count as f64) * 32.0) as usize };
            let bar: String = if self.mode == StyleMode::Plain { "■".repeat(bar_len) } else { (0..bar_len).map(|_| format!("{}■{}", self.fg(10), self.reset_fg())).collect() };
            let line_prefix = format!("  {:>width$} {} {:<bwidth$} |", label, unit.label(), bracket, width = label_width, bwidth = max_count_bracket_len);
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}{}\n", line_prefix, bar)); } else { out.push_str(&format!("{}{}{}{}\n", self.fg(10), line_prefix, self.reset_fg(), bar)); }
        }
        out
    }

    fn distribution_text(&self, durations: &[f64], unit: TimeUnitKind) -> String {
        let mut sorted = durations.to_vec();
        sorted.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut out = String::new();
        for (label, p) in [("10.00",10.0),("25.00",25.0),("50.00",50.0),("75.00",75.0),("90.00",90.0),("95.00",95.0),("99.00",99.0),("99.90",99.9),("99.99",99.99)] {
            let v = percentile(&sorted, p);
            let line = format!("  {}% in {}", label, self.fmt_dur(v, unit));
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", line)); } else { out.push_str(&format!("{}{}{}\n", self.fg(10), line, self.reset_fg())); }
        }
        out
    }

    pub fn print_text(&self, successes: &[SuccessResult], errors: &BTreeMap<String, usize>, total: Duration, start: std::time::Instant) -> String {
        let n_errors: usize = errors.values().sum();
        let stats = compute_stats(successes, n_errors, total);
        let unit = self.time_unit.unwrap_or_else(|| TimeUnitKind::from_slowest(stats.slowest));
        let mut durations: Vec<f64> = successes.iter().map(|r| r.duration.as_secs_f64()).collect();
        durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut out = String::new();
        out.push_str(&format!("{}\n", self.heading("Summary:")));
        let success_color = if stats.success_rate == 1.0 { 10 } else { 9 };
        let sr_line = format!("  Success rate:\t{:.2}%", stats.success_rate * 100.0);
        if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", sr_line)); } else { out.push_str(&format!("{}{}\x1b[1m{}\x1b[0m\n", self.fg(success_color), "", sr_line).replace(&format!("{}{}", self.fg(success_color), ""), &self.fg(success_color))); }
        // Above construction is awkward in plain/color; rebuild correctly below if needed.
        out.push_str(&format!("  Total:\t{}\n", self.fmt_dur(stats.total_secs, unit)));
        let slowest_line = format!("  Slowest:\t{}", self.fmt_dur(stats.slowest, unit));
        let fastest_line = format!("  Fastest:\t{}", self.fmt_dur(stats.fastest, unit));
        let average_line = format!("  Average:\t{}", self.fmt_dur(stats.average, unit));
        if self.mode == StyleMode::Plain {
            out.push_str(&format!("{}\n{}\n{}\n", slowest_line, fastest_line, average_line));
        } else {
            out.push_str(&format!("{}{}{}\n", self.fg(11), slowest_line, self.reset_fg()));
            out.push_str(&format!("{}{}{}\n", self.fg(10), fastest_line, self.reset_fg()));
            out.push_str(&format!("{}{}{}\n", self.fg(14), average_line, self.reset_fg()));
        }
        out.push_str(&format!("  Requests/sec:\t{:.4}\n", stats.requests_per_sec));
        out.push_str("\n");
        out.push_str(&format!("  Total data:\t{}\n", format_bytes(stats.total_data as f64)));
        match stats.size_per_request { Some(v) => out.push_str(&format!("  Size/request:\t{}\n", format_bytes(v as f64))), None => out.push_str("  Size/request:\tNaN\n") }
        out.push_str(&format!("  Size/sec:\t{}\n", format_bytes(stats.size_per_sec)));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Response time histogram:")));
        out.push_str(&self.histogram_text(&durations_raw(successes), unit));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Response time distribution:")));
