        out.push_str(&format!("  DNS-lookup:\t{}, {}, {}\n", self.fmt_dur(lookup.0, unit), self.fmt_dur(lookup.1, unit), self.fmt_dur(lookup.2, unit)));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Status code distribution:")));
