        for s in successes { *status_map.entry(s.status).or_insert(0) += 1; }
        for (code, cnt) in &status_map {
            let line = format!("  [{}] {} responses", code, cnt);
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", line)); } else {
                let color = match code { 100..=199 => 14, 200..=299 => 10, 300..=399 => 15, 400..=499 => 11, _ => 9 };
                out.push_str(&format!("{}{}{}\n", self.fg(color), line, self.reset_fg()));
            }
        }
        if !errors.is_empty() {
            out.push_str("\nError distribution:\n");
            for (msg, cnt) in errors { out.push_str(&format!("  [{}] {}\n", cnt, msg)); }
        }
        let _ = start;
        out
    }

    pub fn print_json(&self, successes: &[SuccessResult], errors: &BTreeMap<String, usize>, total: Duration, start: std::time::Instant) -> String {
        let n_errors: usize = errors.values().sum();
        let stats = compute_stats(successes, n_errors, total);
