            out.push_str(&format!("  \"responseTimeHistogramNotSuccessful\": {},\n", json_histogram(&durations_raw_filtered(successes, false))));
            out.push_str(&format!("  \"latencyPercentilesNotSuccessful\": {}", json_percentiles(&durations_sorted_filtered(successes, false))));
        }
