        out.push_str(&format!("      \"fastest\": {},\n", util::json_f64(lookup.1)));
        out.push_str(&format!("      \"slowest\": {}\n", util::json_f64(lookup.2)));
        out.push_str("    }\n  },\n");
        // status
        let mut status_map: BTreeMap<u16, usize> = BTreeMap::new();
        for s in successes { *status_map.entry(s.status).or_insert(0) += 1; }
        out.push_str("  \"statusCodeDistribution\": {");
        if status_map.is_empty() { out.push_str("},\n"); } else {
            out.push_str("\n");
            let mut parts = Vec::new();
            for (code, cnt) in &status_map { parts.push(format!("    \"{}\": {}", code, cnt)); }
            out.push_str(&parts.join(",\n"));
            out.push_str("\n  },\n");
        }
        out.push_str("  \"errorDistribution\": {");
        if errors.is_empty() { out.push_str("}\n"); } else {
            out.push_str("\n");
            let mut parts = Vec::new();
            for (msg, cnt) in errors { parts.push(format!("    {}: {}", json_escape_str(msg), cnt)); }
            out.push_str(&parts.join(",\n"));
            out.push_str("\n  }\n");
        }
        out.push_str("}");
        out
    }

    pub fn print_csv(&self, successes: &[SuccessResult], start: std::time::Instant) -> String {
        let mut out = String::new();
        out.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
        let mut sorted: Vec<&SuccessResult> = successes.iter().collect();
        sorted.sort_by_key(|r| r.start);
        for r in sorted {
            out.push_str(&format!("{},{},{},{},{},{},{}\n",
                util::f64_display(r.start.duration_since(start).as_secs_f64()),
                util::f64_display(r.dns_lookup.map(|d| d.as_secs_f64()).unwrap_or(0.0)),
                util::f64_display(r.dns_dialup.map(|d| d.as_secs_f64()).unwrap_or(0.0)),
                util::f64_display(r.response_delay().as_secs_f64()),
                util::f64_display(r.duration.as_secs_f64()),
                r.len_bytes, r.status));
        }
        out
    }
}

pub fn durations_raw(successes: &[SuccessResult]) -> Vec<f64> { successes.iter().map(|r| r.duration.as_secs_f64()).collect() }
pub fn durations_sorted(successes: &[SuccessResult]) -> Vec<f64> { let mut v = durations_raw(successes); v.sort_by(|a,b| a.partial_cmp(b).unwrap()); v }
pub fn durations_raw_filtered(successes: &[SuccessResult], successful: bool) -> Vec<f64> { successes.iter().filter(|r| if successful { r.status >= 200 && r.status < 300 } else { !(r.status >= 200 && r.status < 300) }).map(|r| r.duration.as_secs_f64()).collect() }
pub fn durations_sorted_filtered(successes: &[SuccessResult], successful: bool) -> Vec<f64> { let mut v = durations_raw_filtered(successes, successful); v.sort_by(|a,b| a.partial_cmp(b).unwrap()); v }

pub fn detail_triplet(durs: Vec<Duration>) -> (f64, f64, f64) {
    if durs.is_empty() { return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let vals: Vec<f64> = durs.iter().map(|d| d.as_secs_f64()).collect();
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    let fastest = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fastest, slowest)
}

pub fn json_histogram(durations: &[f64]) -> String {
    let hist = histogram(durations);
    // Insert into map with overwrite order (labels in bucket order), duplicate keys collapse.
    let mut map: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    // Use insertion ordered vec to emulate original: keys in bucket order, duplicates overwritten but position kept at first insertion.
    let mut order: Vec<String> = Vec::new();
    let mut vals: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for (label, cnt) in hist.labels.iter().zip(hist.counts.iter()) {
        let key = util::f64_display(*label);
        if !vals.contains_key(&key) { order.push(key.clone()); }
        vals.insert(key, *cnt);
    }
    let _ = &mut map;
    if order.is_empty() { return "{}".to_string(); }
    let mut out = String::from("{");
    // decide multiline if more than... original always pretty prints 2-space indent object; caller handles indent for top-level.
    out.push_str("\n");
    let mut parts = Vec::new();
    for k in &order { parts.push(format!("    \"{}\": {}", k, vals[k])); }
    out.push_str(&parts.join(",\n"));
    out.push_str("\n  }");
    out
}

pub fn json_percentiles(sorted: &[f64]) -> String {
    let mut out = String::from("{\n");
    let mut parts = Vec::new();
    for (k, v) in percentiles_map(sorted) { parts.push(format!("    \"{}\": {}", k, util::json_f64(v))); }
    out.push_str(&parts.join(",\n"));
    out.push_str("\n  }");
    out
}

pub fn indent_json_obj(s: &str, _indent: usize) -> String { s.to_string() }

pub fn json_escape_str(s: &str) -> String {
    let mut out = String::from("\"");
    for ch in s.chars() {
        match ch { '"' => out.push_str("\\\""), '\\' => out.push_str("\\\\"), '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"), c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)), c => out.push(c) }
    }
    out.push('"');
    out
}
