cat > src/printer.rs <<'EOF'
use crate::model::SuccessResult;
use crate::util;
use std::collections::BTreeMap;
use std::time::Duration;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum TimeUnitKind { Ns, Us, Ms, S, M, H }
impl TimeUnitKind {
    pub fn label(&self) -> &'static str {
        match self { TimeUnitKind::Ns => "ns", TimeUnitKind::Us => "us", TimeUnitKind::Ms => "ms", TimeUnitKind::S => "sec", TimeUnitKind::M => "min", TimeUnitKind::H => "hr" }
    }
    pub fn convert(&self, secs: f64) -> f64 {
        match self { TimeUnitKind::Ns => secs * 1e9, TimeUnitKind::Us => secs * 1e6, TimeUnitKind::Ms => secs * 1e3, TimeUnitKind::S => secs, TimeUnitKind::M => secs / 60.0, TimeUnitKind::H => secs / 3600.0 }
    }
    pub fn from_slowest(slowest: f64) -> Self {
        if slowest >= 3600.0 { TimeUnitKind::H } else if slowest >= 60.0 { TimeUnitKind::M } else if slowest >= 1.0 { TimeUnitKind::S } else if slowest >= 0.001 { TimeUnitKind::Ms } else if slowest >= 0.000001 { TimeUnitKind::Us } else { TimeUnitKind::Ns }
    }
    pub fn parse(s: &str) -> Option<Self> {
        match s { "ns" => Some(TimeUnitKind::Ns), "us" => Some(TimeUnitKind::Us), "ms" => Some(TimeUnitKind::Ms), "s" => Some(TimeUnitKind::S), "m" => Some(TimeUnitKind::M), "h" => Some(TimeUnitKind::H), _ => None }
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum StyleMode { Plain, Color, ColorEnvNoColor }

pub struct Printer {
    pub mode: StyleMode,
    pub time_unit: Option<TimeUnitKind>,
    pub stats_success_breakdown: bool,
}

pub fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return f64::NAN; }
    let idx = ((p / 100.0) * sorted.len() as f64) as usize;
    let idx = idx.min(sorted.len() - 1);
    sorted[idx]
}

pub fn percentiles_map(sorted: &[f64]) -> Vec<(String, f64)> {
    let ps: [( &str, f64); 9] = [("p10",10.0),("p25",25.0),("p50",50.0),("p75",75.0),("p90",90.0),("p95",95.0),("p99",99.0),("p99.9",99.9),("p99.99",99.99)];
    ps.iter().map(|(k,p)| (k.to_string(), percentile(sorted, *p))).collect()
}

pub struct Histogram { pub labels: Vec<f64>, pub counts: Vec<usize> }
pub fn histogram(durations: &[f64]) -> Histogram {
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let step = (slowest - fastest) / 10.0;
    let labels: Vec<f64> = (0..=10).map(|i| fastest + step * i as f64).collect();
    let mut counts = vec![0usize; 11];
    for &d in durations {
        let ratio = if slowest > fastest { (d - fastest) / (slowest - fastest) } else { f64::NAN };
        let mut idx = (ratio * 10.0).ceil() as usize;
        if d == fastest { idx = 0; }
        if idx > 10 { idx = 10; }
        counts[idx] += 1;
    }
    Histogram { labels, counts }
}

pub fn format_bytes(v: f64) -> String {
    if !v.is_finite() { return format!("{}", v); }
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut size = v;
    let mut idx = 0usize;
    while size >= 1024.0 && idx < UNITS.len() - 1 { size /= 1024.0; idx += 1; }
    if idx == 0 { format!("{} B", size as i64) } else { format!("{:.2} {}", size, UNITS[idx]) }
}

pub struct Stats {
    pub success_rate: f64,
    pub total_secs: f64,
    pub slowest: f64,
    pub fastest: f64,
    pub average: f64,
    pub requests_per_sec: f64,
    pub total_data: usize,
    pub size_per_request: Option<usize>,
    pub size_per_sec: f64,
}

pub fn compute_stats(successes: &[SuccessResult], n_errors: usize, total: Duration) -> Stats {
    let mut durations: Vec<f64> = successes.iter().map(|r| r.duration.as_secs_f64()).collect();
    durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
    let total_secs = total.as_secs_f64();
    let total_attempts = successes.len() + n_errors;
    let success_rate = successes.len() as f64 / total_attempts as f64;
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let average = if durations.is_empty() { f64::NAN } else { durations.iter().sum::<f64>() / durations.len() as f64 };
    let requests_per_sec = total_attempts as f64 / total_secs;
    let total_data: usize = successes.iter().map(|r| r.len_bytes).sum();
    let size_per_request = if successes.is_empty() { None } else { Some(total_data / successes.len()) };
    let size_per_sec = total_data as f64 / total_secs;
    Stats { success_rate, total_secs, slowest, fastest, average, requests_per_sec, total_data, size_per_request, size_per_sec }
}

pub fn rps_samples(successes: &[SuccessResult], start: std::time::Instant) -> Vec<f64> {
    let mut by_end: Vec<&SuccessResult> = successes.iter().collect();
    by_end.sort_by_key(|r| r.end);
    let mut samples = Vec::new();
    let mut prev = start;
    for r in by_end {
        let dt = r.end.duration_since(prev).as_secs_f64();
        samples.push(1.0 / dt);
        prev = r.end;
    }
    samples.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    samples
}

pub fn mean_std(vals: &[f64]) -> (f64, f64, f64, f64) {
    if vals.is_empty() { return (f64::NAN, f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
    let std = if vals.len() <= 1 { f64::NAN } else {
        let var = vals.iter().map(|v| (v-mean)*(v-mean)).sum::<f64>() / (vals.len() - 1) as f64;
        var.sqrt()
    };
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (mean, std, min, max)
}

impl Printer {
    fn fg(&self, code: u8) -> String {
        match self.mode { StyleMode::Color => format!("\x1b[38;5;{}m", code), StyleMode::ColorEnvNoColor => "\x1b[m".to_string(), StyleMode::Plain => String::new() }
    }
    fn reset_fg(&self) -> String {
        match self.mode { StyleMode::Color => "\x1b[39m".to_string(), StyleMode::ColorEnvNoColor => "\x1b[m".to_string(), StyleMode::Plain => String::new() }
    }
    fn heading(&self, text: &str) -> String {
        match self.mode { StyleMode::Plain => text.to_string(), _ => format!("\x1b[1m\x1b[4m{}\x1b[0m", text) }
    }
    fn fmt_dur(&self, secs: f64, unit: TimeUnitKind) -> String { format!("{:.4} {}", unit.convert(secs), unit.label()) }
    fn fmt_dur3(&self, secs: f64, unit: TimeUnitKind) -> String { format!("{:.3}", unit.convert(secs)) }

    fn histogram_text(&self, durations: &[f64], unit: TimeUnitKind) -> String {
        let hist = histogram(durations);
        let labels_str: Vec<String> = hist.labels.iter().map(|v| self.fmt_dur3(*v, unit)).collect();
        let mut label_width = labels_str.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        if durations.is_empty() { label_width = label_width.max(5); }
        let max_count_bracket_len = hist.counts.iter().max().map(|m| format!("[{}]", m).len()).unwrap_or(3);
        let max_count = *hist.counts.iter().max().unwrap_or(&0);
        let mut out = String::new();
        for (i, cnt) in hist.counts.iter().enumerate() {
            let label = &labels_str[i];
            let bracket = format!("[{}]", cnt);
            let bar_len = if max_count == 0 { 0 } else { ((*cnt as f64 / max_count as f64) * 32.0) as usize };
            let bar: String = if self.mode == StyleMode::Plain { "■".repeat(bar_len) } else { (0..bar_len).map(|_| format!("{}■{}", self.fg(10), self.reset_fg())).collect() };
            let line_prefix = format!("  {:>width$} {} {:<bwidth$} |", label, unit.label(), bracket, width = label_width, bwidth = max_count_bracket_len);
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}{}\n", line_prefix, bar)); } else { out.push_str(&format!("{}{}{}{}\n", self.fg(10), line_prefix, self.reset_fg(), bar)); }
        }
        out
    }

    fn distribution_text(&self, durations: &[f64], unit: TimeUnitKind) -> String {
        let mut sorted = durations.to_vec();
        sorted.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut out = String::new();
        for (label, p) in [("10.00",10.0),("25.00",25.0),("50.00",50.0),("75.00",75.0),("90.00",90.0),("95.00",95.0),("99.00",99.0),("99.90",99.9),("99.99",99.99)] {
            let v = percentile(&sorted, p);
            let line = format!("  {}% in {}", label, self.fmt_dur(v, unit));
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", line)); } else { out.push_str(&format!("{}{}{}\n", self.fg(10), line, self.reset_fg())); }
        }
        out
    }

    pub fn print_text(&self, successes: &[SuccessResult], errors: &BTreeMap<String, usize>, total: Duration, start: std::time::Instant) -> String {
        let n_errors: usize = errors.values().sum();
        let stats = compute_stats(successes, n_errors, total);
        let unit = self.time_unit.unwrap_or_else(|| TimeUnitKind::from_slowest(stats.slowest));
        let mut durations: Vec<f64> = successes.iter().map(|r| r.duration.as_secs_f64()).collect();
        durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut out = String::new();
        out.push_str(&format!("{}\n", self.heading("Summary:")));
        let success_color = if stats.success_rate == 1.0 { 10 } else { 9 };
        let sr_line = format!("  Success rate:\t{:.2}%", stats.success_rate * 100.0);
        if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", sr_line)); } else { out.push_str(&format!("{}{}\x1b[1m{}\x1b[0m\n", self.fg(success_color), "", sr_line).replace(&format!("{}{}", self.fg(success_color), ""), &self.fg(success_color))); }
        // Above construction is awkward in plain/color; rebuild correctly below if needed.
        out.push_str(&format!("  Total:\t{}\n", self.fmt_dur(stats.total_secs, unit)));
        let slowest_line = format!("  Slowest:\t{}", self.fmt_dur(stats.slowest, unit));
        let fastest_line = format!("  Fastest:\t{}", self.fmt_dur(stats.fastest, unit));
        let average_line = format!("  Average:\t{}", self.fmt_dur(stats.average, unit));
        if self.mode == StyleMode::Plain {
            out.push_str(&format!("{}\n{}\n{}\n", slowest_line, fastest_line, average_line));
        } else {
            out.push_str(&format!("{}{}{}\n", self.fg(11), slowest_line, self.reset_fg()));
            out.push_str(&format!("{}{}{}\n", self.fg(10), fastest_line, self.reset_fg()));
            out.push_str(&format!("{}{}{}\n", self.fg(14), average_line, self.reset_fg()));
        }
        out.push_str(&format!("  Requests/sec:\t{:.4}\n", stats.requests_per_sec));
        out.push_str("\n");
        out.push_str(&format!("  Total data:\t{}\n", format_bytes(stats.total_data as f64)));
        match stats.size_per_request { Some(v) => out.push_str(&format!("  Size/request:\t{}\n", format_bytes(v as f64))), None => out.push_str("  Size/request:\tNaN\n") }
        out.push_str(&format!("  Size/sec:\t{}\n", format_bytes(stats.size_per_sec)));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Response time histogram:")));
        out.push_str(&self.histogram_text(&durations_raw(successes), unit));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Response time distribution:")));
        out.push_str(&self.distribution_text(&durations_raw(successes), unit));
        if self.stats_success_breakdown {
            let succ_durs = durations_raw_filtered(successes, true);
            let nonsucc_durs = durations_raw_filtered(successes, false);
            out.push_str("\n");
            out.push_str(&format!("{}\n", self.heading("Response time histogram (2xx only):")));
            out.push_str(&self.histogram_text(&succ_durs, unit));
            out.push_str("\n");
            out.push_str(&format!("{}\n", self.heading("Response time distribution (2xx only):")));
            out.push_str(&self.distribution_text(&succ_durs, unit));
            out.push_str("\n");
            out.push_str(&format!("{}\n", self.heading("Response time histogram (4xx + 5xx only):")));
            out.push_str(&self.histogram_text(&nonsucc_durs, unit));
            out.push_str("\n");
            out.push_str(&format!("{}\n", self.heading("Response time distribution (4xx + 5xx only):")));
            out.push_str(&self.distribution_text(&nonsucc_durs, unit));
        }
        out.push_str("\n\n");
        out.push_str(&format!("{}\n", self.heading("Details (average, fastest, slowest):")));
        let dialup = detail_triplet(successes.iter().filter_map(|r| r.dns_dialup).collect());
        let lookup = detail_triplet(successes.iter().filter_map(|r| r.dns_lookup).collect());
        out.push_str(&format!("  DNS+dialup:\t{}, {}, {}\n", self.fmt_dur(dialup.0, unit), self.fmt_dur(dialup.1, unit), self.fmt_dur(dialup.2, unit)));
        out.push_str(&format!("  DNS-lookup:\t{}, {}, {}\n", self.fmt_dur(lookup.0, unit), self.fmt_dur(lookup.1, unit), self.fmt_dur(lookup.2, unit)));
        out.push_str("\n");
        out.push_str(&format!("{}\n", self.heading("Status code distribution:")));
        let mut status_map: BTreeMap<u16, usize> = BTreeMap::new();
        for s in successes { *status_map.entry(s.status).or_insert(0) += 1; }
        for (code, cnt) in &status_map {
            let line = format!("  [{}] {} responses", code, cnt);
            if self.mode == StyleMode::Plain { out.push_str(&format!("{}\n", line)); } else {
                let color = match code { 100..=199 => 14, 200..=299 => 10, 300..=399 => 15, 400..=499 => 11, _ => 9 };
                out.push_str(&format!("{}{}{}\n", self.fg(color), line, self.reset_fg()));
            }
        }
        if !errors.is_empty() {
            out.push_str("\nError distribution:\n");
            for (msg, cnt) in errors { out.push_str(&format!("  [{}] {}\n", cnt, msg)); }
        }
        let _ = start;
        out
    }

    pub fn print_json(&self, successes: &[SuccessResult], errors: &BTreeMap<String, usize>, total: Duration, start: std::time::Instant) -> String {
        let n_errors: usize = errors.values().sum();
        let stats = compute_stats(successes, n_errors, total);
        let mut out = String::new();
        out.push_str("{\n  \"summary\": {\n");
        out.push_str(&format!("    \"successRate\": {},\n", util::json_f64(stats.success_rate)));
        out.push_str(&format!("    \"total\": {},\n", util::json_f64(stats.total_secs)));
        out.push_str(&format!("    \"slowest\": {},\n", util::json_f64(stats.slowest)));
        out.push_str(&format!("    \"fastest\": {},\n", util::json_f64(stats.fastest)));
        out.push_str(&format!("    \"average\": {},\n", util::json_f64(stats.average)));
        out.push_str(&format!("    \"requestsPerSec\": {},\n", util::json_f64(stats.requests_per_sec)));
        out.push_str(&format!("    \"totalData\": {},\n", stats.total_data));
        match stats.size_per_request { Some(v) => out.push_str(&format!("    \"sizePerRequest\": {},\n", v)), None => out.push_str("    \"sizePerRequest\": null,\n") }
        out.push_str(&format!("    \"sizePerSec\": {}\n", util::json_f64(stats.size_per_sec)));
        out.push_str("  },\n");
        // histogram
        out.push_str(&format!("  \"responseTimeHistogram\": {},\n", json_histogram(&durations_raw(successes))));
        out.push_str(&format!("  \"latencyPercentiles\": {}", json_percentiles(&durations_sorted(successes))));
        if self.stats_success_breakdown {
            out.push_str(",\n");
            out.push_str(&format!("  \"responseTimeHistogramSuccessful\": {},\n", json_histogram(&durations_raw_filtered(successes, true))));
            out.push_str(&format!("  \"latencyPercentilesSuccessful\": {},\n", json_percentiles(&durations_sorted_filtered(successes, true))));
            out.push_str(&format!("  \"responseTimeHistogramNotSuccessful\": {},\n", json_histogram(&durations_raw_filtered(successes, false))));
            out.push_str(&format!("  \"latencyPercentilesNotSuccessful\": {}", json_percentiles(&durations_sorted_filtered(successes, false))));
        }
        out.push_str(",\n");
        // rps
        let samples = rps_samples(successes, start);
        let (mean, std, minv, maxv) = mean_std(&samples);
        out.push_str("  \"rps\": {\n");
        out.push_str(&format!("    \"mean\": {},\n", util::json_f64(mean)));
        out.push_str(&format!("    \"stddev\": {},\n", util::json_f64(std)));
        out.push_str(&format!("    \"max\": {},\n", util::json_f64(maxv)));
        out.push_str(&format!("    \"min\": {},\n", util::json_f64(minv)));
        out.push_str(&format!("    \"percentiles\": {}", indent_json_obj(&json_percentiles(&samples), 4)));
        out.push_str("\n  },\n");
        // details
        let dialup = detail_triplet(successes.iter().filter_map(|r| r.dns_dialup).collect());
        let lookup = detail_triplet(successes.iter().filter_map(|r| r.dns_lookup).collect());
        out.push_str("  \"details\": {\n");
        out.push_str("    \"DNSDialup\": {\n");
        out.push_str(&format!("      \"average\": {},\n", util::json_f64(dialup.0)));
        out.push_str(&format!("      \"fastest\": {},\n", util::json_f64(dialup.1)));
        out.push_str(&format!("      \"slowest\": {}\n", util::json_f64(dialup.2)));
        out.push_str("    },\n");
        out.push_str("    \"DNSLookup\": {\n");
        out.push_str(&format!("      \"average\": {},\n", util::json_f64(lookup.0)));
        out.push_str(&format!("      \"fastest\": {},\n", util::json_f64(lookup.1)));
        out.push_str(&format!("      \"slowest\": {}\n", util::json_f64(lookup.2)));
        out.push_str("    }\n  },\n");
        // status
        let mut status_map: BTreeMap<u16, usize> = BTreeMap::new();
        for s in successes { *status_map.entry(s.status).or_insert(0) += 1; }
        out.push_str("  \"statusCodeDistribution\": {");
        if status_map.is_empty() { out.push_str("},\n"); } else {
            out.push_str("\n");
            let mut parts = Vec::new();
            for (code, cnt) in &status_map { parts.push(format!("    \"{}\": {}", code, cnt)); }
            out.push_str(&parts.join(",\n"));
            out.push_str("\n  },\n");
        }
        out.push_str("  \"errorDistribution\": {");
        if errors.is_empty() { out.push_str("}\n"); } else {
            out.push_str("\n");
            let mut parts = Vec::new();
            for (msg, cnt) in errors { parts.push(format!("    {}: {}", json_escape_str(msg), cnt)); }
            out.push_str(&parts.join(",\n"));
            out.push_str("\n  }\n");
        }
        out.push_str("}");
        out
    }

    pub fn print_csv(&self, successes: &[SuccessResult], start: std::time::Instant) -> String {
        let mut out = String::new();
        out.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
        let mut sorted: Vec<&SuccessResult> = successes.iter().collect();
        sorted.sort_by_key(|r| r.start);
        for r in sorted {
            out.push_str(&format!("{},{},{},{},{},{},{}\n",
                util::f64_display(r.start.duration_since(start).as_secs_f64()),
                util::f64_display(r.dns_lookup.map(|d| d.as_secs_f64()).unwrap_or(0.0)),
                util::f64_display(r.dns_dialup.map(|d| d.as_secs_f64()).unwrap_or(0.0)),
                util::f64_display(r.response_delay().as_secs_f64()),
                util::f64_display(r.duration.as_secs_f64()),
                r.len_bytes, r.status));
        }
        out
    }
}

pub fn durations_raw(successes: &[SuccessResult]) -> Vec<f64> { successes.iter().map(|r| r.duration.as_secs_f64()).collect() }
pub fn durations_sorted(successes: &[SuccessResult]) -> Vec<f64> { let mut v = durations_raw(successes); v.sort_by(|a,b| a.partial_cmp(b).unwrap()); v }
pub fn durations_raw_filtered(successes: &[SuccessResult], successful: bool) -> Vec<f64> { successes.iter().filter(|r| if successful { r.status >= 200 && r.status < 300 } else { !(r.status >= 200 && r.status < 300) }).map(|r| r.duration.as_secs_f64()).collect() }
pub fn durations_sorted_filtered(successes: &[SuccessResult], successful: bool) -> Vec<f64> { let mut v = durations_raw_filtered(successes, successful); v.sort_by(|a,b| a.partial_cmp(b).unwrap()); v }

pub fn detail_triplet(durs: Vec<Duration>) -> (f64, f64, f64) {
    if durs.is_empty() { return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let vals: Vec<f64> = durs.iter().map(|d| d.as_secs_f64()).collect();
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    let fastest = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fastest, slowest)
}

pub fn json_histogram(durations: &[f64]) -> String {
    let hist = histogram(durations);
    // Insert into map with overwrite order (labels in bucket order), duplicate keys collapse.
    let mut map: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    // Use insertion ordered vec to emulate original: keys in bucket order, duplicates overwritten but position kept at first insertion.
    let mut order: Vec<String> = Vec::new();
    let mut vals: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for (label, cnt) in hist.labels.iter().zip(hist.counts.iter()) {
        let key = util::f64_display(*label);
        if !vals.contains_key(&key) { order.push(key.clone()); }
        vals.insert(key, *cnt);
    }
    let _ = &mut map;
    if order.is_empty() { return "{}".to_string(); }
    let mut out = String::from("{");
    // decide multiline if more than... original always pretty prints 2-space indent object; caller handles indent for top-level.
    out.push_str("\n");
    let mut parts = Vec::new();
    for k in &order { parts.push(format!("    \"{}\": {}", k, vals[k])); }
    out.push_str(&parts.join(",\n"));
    out.push_str("\n  }");
    out
}

pub fn json_percentiles(sorted: &[f64]) -> String {
    let mut out = String::from("{\n");
    let mut parts = Vec::new();
    for (k, v) in percentiles_map(sorted) { parts.push(format!("    \"{}\": {}", k, util::json_f64(v))); }
    out.push_str(&parts.join(",\n"));
    out.push_str("\n  }");
    out
}

pub fn indent_json_obj(s: &str, _indent: usize) -> String { s.to_string() }

pub fn json_escape_str(s: &str) -> String {
    let mut out = String::from("\"");
    for ch in s.chars() {
        match ch { '"' => out.push_str("\\\""), '\\' => out.push_str("\\\\"), '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"), c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)), c => out.push(c) }
    }
    out.push('"');
    out
}
