#[derive(Clone, Debug)]
pub struct DynamicEntry { pub name: Vec<u8>, pub value: Vec<u8>, pub size: usize }

pub struct HpackDecoder {
    pub dynamic: Vec<DynamicEntry>, // front = newest
    pub max_size: usize,
}
impl HpackDecoder {
    pub fn new() -> Self { HpackDecoder { dynamic: Vec::new(), max_size: 4096 } }
    fn entry(&self, idx: u64) -> Result<(Vec<u8>, Vec<u8>), String> {
        if idx == 0 { return Err("hpack index zero".to_string()); }
        if (idx as usize) <= STATIC_TABLE.len() { let (n,v) = STATIC_TABLE[(idx-1) as usize]; return Ok((n.as_bytes().to_vec(), v.as_bytes().to_vec())); }
        let dyn_idx = (idx as usize) - STATIC_TABLE.len() - 1;
        if dyn_idx < self.dynamic.len() { let e = &self.dynamic[dyn_idx]; return Ok((e.name.clone(), e.value.clone())); }
        Err("hpack index out of range".to_string())
    }
    fn name_by_index(&self, idx: u64, data: &[u8], pos: &mut usize) -> Result<Vec<u8>, String> {
        if idx == 0 { read_string(data, pos) } else { Ok(self.entry(idx)?.0) }
    }
    fn insert_dynamic(&mut self, name: Vec<u8>, value: Vec<u8>) {
        let size = name.len() + value.len() + 32;
        self.dynamic.insert(0, DynamicEntry { name, value, size });
        let mut total: usize = self.dynamic.iter().map(|e| e.size).sum();
        while total > self.max_size {
            if let Some(e) = self.dynamic.pop() { total -= e.size; } else { break; }
        }
    }
    pub fn decode(&mut self, data: &[u8]) -> Result<Vec<(Vec<u8>, Vec<u8>)>, String> {
        let mut out = Vec::new();
        let mut pos = 0usize;
        while pos < data.len() {
            let b = data[pos];
            if b & 0x80 != 0 {
                let idx = read_int(data, &mut pos, 7)?;
                out.push(self.entry(idx)?);
            } else if b & 0xc0 == 0x40 {
                let idx = read_int(data, &mut pos, 6)?;
                let name = self.name_by_index(idx, data, &mut pos)?;
                let value = read_string(data, &mut pos)?;
                self.insert_dynamic(name.clone(), value.clone());
                out.push((name, value));
            } else if b & 0xe0 == 0x20 {
                let new_size = read_int(data, &mut pos, 5)? as usize;
                self.max_size = new_size;
                let mut total: usize = self.dynamic.iter().map(|e| e.size).sum();
                while total > self.max_size { if let Some(e) = self.dynamic.pop() { total -= e.size; } else { break; } }
            } else {
                // without indexing (0000) or never indexed (0001)
                let idx = read_int(data, &mut pos, 4)?;
                let name = self.name_by_index(idx, data, &mut pos)?;
                let value = read_string(data, &mut pos)?;
                out.push((name, value));
            }
        }
        Ok(out)
    }
}

pub fn write_int(out: &mut Vec<u8>, prefix_bits: u8, prefix_high: u8, value: u64) {
    let mask = if prefix_bits >= 8 { 0xff } else { (1u64 << prefix_bits) - 1 };
    if value < mask {
        out.push(prefix_high | value as u8);
    } else {
        out.push(prefix_high | mask as u8);
        let mut v = value - mask;
        loop {
            let mut b = (v & 0x7f) as u8; v >>= 7;
            if v > 0 { b |= 0x80; out.push(b); } else { out.push(b); break; }
        }
    }
}
pub fn write_string(out: &mut Vec<u8>, bytes: &[u8]) {
    write_int(out, 7, 0, bytes.len() as u64);
    out.extend_from_slice(bytes);
}
pub fn write_literal_indexed_name(out: &mut Vec<u8>, name_index: u64, value: &[u8]) {
    write_int(out, 4, 0, name_index);
    write_string(out, value);
}
pub fn write_literal_new_name(out: &mut Vec<u8>, name: &[u8], value: &[u8]) {
    write_int(out, 4, 0, 0);
    write_string(out, name);
    write_string(out, value);
}
