pub enum Stream {
    Plain(TcpStream),
    Tls(Box<TlsStream>),
    Unix(std::os::unix::net::UnixStream),
}
impl Stream {
    pub fn set_timeouts(&self, read: Option<Duration>, write: Option<Duration>) {
        match self {
            Stream::Plain(s) => { let _ = s.set_read_timeout(read); let _ = s.set_write_timeout(write); }
            Stream::Tls(s) => { let _ = s.set_read_timeout(read); let _ = s.set_write_timeout(write); }
            Stream::Unix(s) => { let _ = s.set_read_timeout(read); let _ = s.set_write_timeout(write); }
        }
    }
    pub fn fd(&self) -> i32 {
        match self { Stream::Plain(s) => s.as_raw_fd(), Stream::Tls(s) => s.inner().as_raw_fd(), Stream::Unix(s) => s.as_raw_fd() }
    }
    pub fn shutdown_write(&self) { match self { Stream::Plain(s) => { let _ = s.shutdown(std::net::Shutdown::Both); }, Stream::Tls(_) => {}, Stream::Unix(s) => { let _ = s.shutdown(std::net::Shutdown::Both); } } }
}
impl Read for Stream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self { Stream::Plain(s) => s.read(buf), Stream::Tls(s) => s.read(buf), Stream::Unix(s) => s.read(buf) }
    }
}
impl Write for Stream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self { Stream::Plain(s) => s.write(buf), Stream::Tls(s) => s.write(buf), Stream::Unix(s) => s.write(buf) }
    }
    fn flush(&mut self) -> io::Result<()> { match self { Stream::Plain(s) => s.flush(), Stream::Tls(s) => s.flush(), Stream::Unix(s) => s.flush() } }
}

#[derive(Clone)]
pub struct ReqCtx {
    pub request_deadline: Option<Instant>,
    pub abort_deadline: Option<Instant>,
    pub collect_body: bool,
}

impl ReqCtx {
    pub fn check_fail(&self) -> Option<String> {
        if INTERRUPTED.load(Ordering::SeqCst) { return Some(ERR_ABORTED.to_string()); }
        let now = Instant::now();
        if let Some(d) = self.request_deadline { if now >= d { return Some(ERR_TIMEOUT.to_string()); } }
        if let Some(d) = self.abort_deadline { if now >= d { return Some(ERR_ABORTED.to_string()); } }
        None
    }
    pub fn wait_duration(&self) -> Duration {
        let now = Instant::now();
        let mut wait = Duration::from_millis(50);
        if let Some(d) = self.request_deadline { wait = wait.min(d.saturating_duration_since(now)); }
        if let Some(d) = self.abort_deadline { wait = wait.min(d.saturating_duration_since(now)); }
        if wait.is_zero() { wait = Duration::from_millis(1); }
        wait
    }
}

