pub struct H1Conn {
    pub stream: Stream,
    pub buf: Vec<u8>,
    pub pos: usize,
    pub origin: OriginKey,
    pub dns_info: Option<(Duration, Duration)>,
    pub used_before: bool,
    pub closed_by_server_hint: bool,
}
impl H1Conn {
    pub fn take_dns_info(&mut self) -> Option<(Duration, Duration)> { self.dns_info.take() }
    fn available(&self) -> usize { self.buf.len().saturating_sub(self.pos) }
    fn compact(&mut self) { if self.pos > 0 { self.buf.drain(..self.pos); self.pos = 0; } }
    // returns Ok(n), Err(EOF sentinel), or error string
    fn fill(&mut self, ctx: &ReqCtx) -> Result<usize, String> {
        if let Some(e) = ctx.check_fail() { return Err(e); }
        let wait = ctx.wait_duration();
        self.stream.set_timeouts(Some(wait), Some(wait));
        let mut tmp = [0u8; 16384];
        match self.stream.read(&mut tmp) {
            Ok(0) => Err("__EOF__".to_string()),
            Ok(n) => { if self.pos > 65536 { self.compact(); } self.buf.extend_from_slice(&tmp[..n]); Ok(n) }
            Err(e) if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut => {
                if let Some(err) = ctx.check_fail() { Err(err) } else { self.fill(ctx) }
            }
            Err(e) if e.kind() == io::ErrorKind::Interrupted => self.fill(ctx),
            Err(e) => Err(io_error_string(&e)),
        }
    }
    fn read_line(&mut self, ctx: &ReqCtx) -> Result<Vec<u8>, String> {
        loop {
            // search for \n in available
            if self.available() > 0 {
                let slice = &self.buf[self.pos..];
                if let Some(idx) = slice.iter().position(|&b| b == b'\n') {
                    let mut line = slice[..idx].to_vec();
                    self.pos += idx + 1;
                    if line.ends_with(b"\r") { line.pop(); }
                    return Ok(line);
                }
            }
            match self.fill(ctx) { Ok(_) => continue, Err(e) => return Err(e) }
        }
    }
    fn read_body_bytes(&mut self, ctx: &ReqCtx, max_to_read: usize, out: &mut Vec<u8>, collect: bool, first_byte: &mut Option<Instant>, total_counter: &mut usize) -> Result<(), String> {
        // reads up to max_to_read bytes (or 16k segment)
        if max_to_read == 0 { return Ok(()); }
        if self.available() == 0 {
            match self.fill(ctx) { Ok(_) => {}, Err(e) => return Err(e) }
        }
        if self.available() > 0 {
            if first_byte.is_none() { *first_byte = Some(Instant::now()); }
            let take = self.available().min(max_to_read);
            if collect { out.extend_from_slice(&self.buf[self.pos..self.pos+take]); }
            *total_counter += take;
            self.pos += take;
            if self.pos == self.buf.len() { self.buf.clear(); self.pos = 0; }
            Ok(())
        } else { Ok(()) }
    }
}

pub fn io_error_string(e: &io::Error) -> String {
    // std::io::Error Display already gives e.g. "Connection refused (os error 111)"
    format!("{}", e)
}

pub fn resolve_host(host: &str, port: u16, ipv4_only: bool, ipv6_only: bool) -> Result<(Vec<SocketAddr>, Duration), String> {
    let start = Instant::now();
    let mut addrs: Vec<SocketAddr> = Vec::new();
    if let Ok(ip) = host.parse::<std::net::IpAddr>() {
        addrs.push(SocketAddr::new(ip, port));
    } else if host == "localhost" || host.ends_with(".localhost") {
        if !ipv4_only { addrs.push(SocketAddr::new("::1".parse().unwrap(), port)); }
        if !ipv6_only { addrs.push(SocketAddr::new("127.0.0.1".parse().unwrap(), port)); }
        // Our connect loop tries in order; put IPv4 first to match typical localhost behaviour when both allowed.
        if !ipv4_only && !ipv6_only { addrs.reverse(); }
    } else if host.is_empty() {
        return Err("proto error: io error: Network is unreachable (os error 101)".to_string());
    } else {
        match (host, port).to_socket_addrs() {
            Ok(iter) => { addrs = iter.collect(); }
            Err(_) => { return Err("proto error: io error: Network is unreachable (os error 101)".to_string()); }
        }
        if ipv4_only { addrs.retain(|a| a.is_ipv4()); }
        if ipv6_only { addrs.retain(|a| a.is_ipv6()); }
        if addrs.is_empty() { return Err("proto error: io error: Network is unreachable (os error 101)".to_string()); }
    }
    Ok((addrs, start.elapsed()))
}

pub fn set_nodelay(stream: &Stream) {
    let fd = stream.fd();
    if fd >= 0 {
        unsafe {
            let val: i32 = 1;
            libc::setsockopt(fd, libc::IPPROTO_TCP, libc::TCP_NODELAY, &val as *const i32 as *const libc::c_void, std::mem::size_of::<i32>() as u32);
        }
    }
}

pub fn peek_eof(stream: &Stream) -> bool {
    match stream {
        Stream::Tls(_) => false,
        _ => {
            let fd = stream.fd();
            if fd < 0 { return false; }
            unsafe {
                let mut b = [0u8; 1];
                let n = libc::recv(fd, b.as_mut_ptr() as *mut libc::c_void, 1, libc::MSG_PEEK | libc::MSG_DONTWAIT);
                n == 0
            }
        }
    }
}
