    pub fn new(cfg: std::sync::Arc<ClientConfig>) -> Self { WorkerClient { cfg, conn: None, h2conn: None, rng: crate::util::Rng::new() } }

    fn url_port(url: &Url) -> u16 {
        if let Some(p) = url.port() { return p; }
        match url.scheme() { "https" | "wss" => 443, _ => 80 }
