    fn connect_target(&mut self, url: &Url) -> (String, u16) {
        let host = url.host_str().unwrap_or("").to_string();
        let port = Self::url_port(url);
        let matches: Vec<&ConnectToEntry> = self.cfg.connect_to.iter().filter(|e| e.requested_host == host && e.requested_port == port).collect();
