    fn origin_for(&mut self, url: &Url, built: &BuiltRequest) -> OriginKey {
        if let Some(path) = &self.cfg.unix_socket {
            if url.scheme() != "https" { return OriginKey { scheme: "unix".into(), host: path.clone(), port: 0, tls: false, unix: Some(path.clone()), proxy: None }; }
        }
        if let Some(proxy) = &self.cfg.proxy {
            if url.scheme() == "https" {
                return OriginKey { scheme: "https".into(), host: url.host_str().unwrap_or("").into(), port: Self::url_port(url), tls: true, unix: None, proxy: Some(format!("{}://{}", proxy.scheme, proxy.authority)) };
            } else {
                return OriginKey { scheme: url.scheme().into(), host: proxy.host.clone(), port: proxy.port, tls: proxy.scheme == "https", unix: None, proxy: Some(format!("{}://{}", proxy.scheme, proxy.authority)) };
            }
        }
