        if !version_token.starts_with("HTTP/") { return Err("invalid HTTP version parsed".to_string()); }
        let ver = &version_token[5..];
        let version_label = match ver { "0.9" => "HTTP/0.9", "1.0" => "HTTP/1.0", "1.1" => "HTTP/1.1", _ => return Err("invalid HTTP version parsed".to_string()) }.to_string();
        let status_token = parts.next().unwrap_or("");
        if status_token.len() != 3 || !status_token.bytes().all(|b| b.is_ascii_digit()) { return Err("invalid HTTP status-code parsed".to_string()); }
        let status: u16 = status_token.parse().map_err(|_| "invalid HTTP status-code parsed".to_string())?;
        if !(100..=999).contains(&status) { return Err("invalid HTTP status-code parsed".to_string()); }
        let mut headers: Vec<HeaderKV> = Vec::new();
        loop {
            let line = self.read_line(ctx).map_err(|e| if e == "__EOF__" { "connection closed before message completed".to_string() } else { e })?;
            if line.is_empty() { break; }
            let colon = line.iter().position(|&b| b == b':').ok_or_else(|| "invalid HTTP header parsed".to_string())?;
            let name_bytes = &line[..colon];
            if name_bytes.is_empty() || !name_bytes.iter().all(|&b| is_token_char(b)) { return Err("invalid HTTP header name".to_string()); }
            let name = String::from_utf8_lossy(name_bytes).to_ascii_lowercase();
            let mut value = line[colon+1..].to_vec();
            // trim OWS
            while value.first().map(|b| *b == b' ' || *b == b'\t').unwrap_or(false) { value.remove(0); }
            while value.last().map(|b| *b == b' ' || *b == b'\t').unwrap_or(false) { value.pop(); }
            headers.push(HeaderKV { name, value });
            if headers.len() > 10000 { return Err("invalid HTTP header parsed".to_string()); }
        }
        Ok((status, version_label, headers))
    }

    fn read_chunked(&mut self, ctx: &ReqCtx, body: &mut Vec<u8>, collect: bool, first_byte: &mut Option<Instant>, total: &mut usize) -> Result<(), String> {
        loop {
            let line = self.read_line(ctx).map_err(|e| if e == "__EOF__" { "error reading a body from connection".to_string() } else { e })?;
            let line_str = String::from_utf8_lossy(&line).to_string();
            let size_str = line_str.split(';').next().unwrap_or("").trim();
            let size = usize::from_str_radix(size_str, 16).map_err(|_| "invalid chunk size".to_string())?;
            if size == 0 {
                // trailers until empty line
                loop { let l = self.read_line(ctx).map_err(|e| if e == "__EOF__" { "error reading a body from connection".to_string() } else { e })?; if l.is_empty() { break; } }
                return Ok(());
            }
            let mut remaining = size;
            while remaining > 0 {
                let before = *total;
                let want = remaining.min(16384);
                self.read_body_bytes(ctx, want, body, collect, first_byte, total).map_err(|e| if e == "__EOF__" { "error reading a body from connection".to_string() } else { e })?;
                if *total == before { return Err("error reading a body from connection".to_string()); }
                remaining -= *total - before;
            }
            // trailing CRLF after chunk
            let crlf = self.read_line(ctx).map_err(|e| if e == "__EOF__" { "error reading a body from connection".to_string() } else { e })?;
            if !crlf.is_empty() { /* Some servers may omit? Treat non-empty as error */ return Err("invalid chunk size".to_string()); }
        }
    }

    fn read_until_eof(&mut self, ctx: &ReqCtx, body: &mut Vec<u8>, collect: bool, first_byte: &mut Option<Instant>, total: &mut usize) -> Result<(), String> {
        loop {
            if self.available() == 0 {
                match self.fill(ctx) { Ok(_) => {}, Err(e) => { if e == "__EOF__" { return Ok(()); } return Err(e); } }
            }
            let before = *total;
            self.read_body_bytes(ctx, 16384, body, collect, first_byte, total)?;
            if *total == before {
                match self.fill(ctx) { Ok(_) => {}, Err(e) => { if e == "__EOF__" { return Ok(()); } return Err(e); } }
            }
        }
    }
}

pub fn is_token_char(b: u8) -> bool {
    matches!(b, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~') || b.is_ascii_alphanumeric()
}

impl BuiltRequest {
    pub fn uri_display_for_wire(&self) -> String { self.uri_display.clone() }
}
