    out.push(((payload.len() >> 16) & 0xff) as u8); out.push(((payload.len() >> 8) & 0xff) as u8); out.push((payload.len() & 0xff) as u8);
    out.push(ty); out.push(flags);
    out.extend_from_slice(&(sid & 0x7fffffff).to_be_bytes());
    out.extend_from_slice(payload);
}

