        // contribution
        let mut contrib = int_part.checked_mul(unit_ns).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?;
        if !frac_digits.is_empty() {
            // fractional contribution in ns must be an integer
            let mut num: u128 = 0;
            for d in &frac_digits { num = num.checked_mul(10).and_then(|v| v.checked_add((*d - b'0') as u128)).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?; }
            let denom = 10u128.checked_pow(frac_digits.len() as u32).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?;
            let prod = num.checked_mul(unit_ns).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?;
            if prod % denom != 0 { return Err("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string()); }
            contrib = contrib.checked_add(prod / denom).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?;
        }
        total_ns = total_ns.checked_add(contrib).ok_or_else(|| "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string())?;
        any = true;
        let _ = num_start;
        // skip spaces before next component
        while pos < bytes.len() && bytes[pos] == b' ' { pos += 1; }
        // Loop: if EOF we finish; if next char is invalid (not digit) loop header will handle.
        // However humantime treats a char like Greek mu after a number as "invalid character".
        if pos < bytes.len() && !bytes[pos].is_ascii_digit() {
            // Determine if it's a start of something invalid: peek char
            let c = s[pos..].chars().next().unwrap();
            if c == '\u{3bc}' { return Err(format!("invalid character at {}", pos)); }
            // Otherwise let loop produce "expected number at pos"
        }
    }
    if !any { return Err("value was empty".to_string()); }
    // Duration must fit into u64 seconds + nanos
    let secs = total_ns / 1_000_000_000u128;
    let nanos = (total_ns % 1_000_000_000u128) as u32;
    if secs > u64::MAX as u128 { return Err("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string()); }
    Ok(Duration::new(secs as u64, nanos))
}

fn is_header_name_valid(name: &str) -> bool {
    !name.is_empty() && name.bytes().all(|b| client::is_token_char(b))
}
fn parse_header_value_bytes(s: &str) -> Result<Vec<u8>, String> {
    let bytes = s.as_bytes();
    for &b in bytes { if !(b == 9 || (32..=126).contains(&b) || b >= 128) { return Err("failed to parse header value".to_string()); } }
    Ok(bytes.to_vec())
}
fn parse_header(s: &str) -> Result<HeaderKV, String> {
    let colon = s.find(':').ok_or_else(|| "Parse header".to_string())?;
    let name = &s[..colon];
    if !is_header_name_valid(name) { return Err("invalid HTTP header name".to_string()); }
    let after = &s[colon+1..];
    let value_str = after.trim_start_matches(' ');
    let value = parse_header_value_bytes(value_str)?;
    Ok(HeaderKV { name: name.to_ascii_lowercase(), value })
}
fn parse_method(s: &str) -> Result<String, String> {
    if s.is_empty() || !s.bytes().all(|b| client::is_token_char(b)) { return Err("invalid HTTP method".to_string()); }
    Ok(s.to_string())
}
fn parse_connect_to(s: &str) -> Result<ConnectToEntry, String> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() < 4 { return Err("syntax for --connect-to is host:port:target_host:target_port".to_string()); }
    let n = parts.len();
    let target_port_str = parts[n-1];
    let target_host = parts[n-2].to_string();
    let requested_port_str = parts[n-3];
    let requested_host = parts[..n-3].join(":");
    let requested_port: u16 = requested_port_str.parse().map_err(|e: std::num::ParseIntError| format!("requested port must be an u16, but got {}: {}", requested_port_str, e))?;
    let target_port: u16 = target_port_str.parse().map_err(|e: std::num::ParseIntError| format!("target port must be an u16, but got {}: {}", target_port_str, e))?;
    Ok(ConnectToEntry { requested_host, requested_port, target_host, target_port })
}

fn build_cli() -> Command {
    Command::new("oha")
        .version("1.12.1")
