        .arg(Arg::new("n_connections").short('c').value_name("N_CONNECTIONS").help("Number of connections to run concurrently. You may should increase limit to number of open files for larger `-c`.").default_value("50").value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("n_http2_parallel").short('p').value_name("N_HTTP2_PARALLEL").help("Number of parallel requests to send on HTTP/2. `oha` will run c * p concurrent workers in total.").default_value("1").value_parser(clap::value_parser!(usize)))
