// ---------- value parsers ----------
fn parse_n_requests(s: &str) -> Result<usize, String> {
    let t = s.trim();
    let lower = t.to_ascii_lowercase();
    if lower.ends_with('k') {
        let num = &t[..t.len()-1];
        let v: f64 = num.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
        Ok((v * 1000.0) as usize)
    } else if lower.ends_with('m') {
        let num = &t[..t.len()-1];
        let v: f64 = num.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
