    let url_gen: UrlGenerator = if opts.urls_from_file {
        UrlGenerator::new_from_file(&opts.url_arg)?
    } else if opts.rand_regex_url {
        UrlGenerator::new_rand_regex(&opts.url_arg, opts.max_repeat)?
    } else {
        UrlGenerator::new_static(&opts.url_arg)?
    };

    if let Some(n) = opts.dump_urls {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        for _ in 0..n {
            let u = url_gen.generate()?;
            writeln!(lock, "{}", u).map_err(|e| e.to_string())?;
        }
        return Ok(0);
    }

    // Body
    let (body_template, form_boundary_ct) = build_body(&opts)?;
    if let Some(ct) = form_boundary_ct { opts.form_content_type = Some(ct); }
    // Validate auth/AWS and header values by building a sample request (also reads required files ordering).
    // TLS config (reads cacert/cert/key contents, may panic in original fashion for bad client material).
    let tls_config = build_tls_config(&opts)?;
    // Build sample to validate header values/auth (discard)
    {
        let sample_url = url_gen.generate()?;
        let sample_body = match &body_template { BodyTemplate::Fixed(b) => b.clone(), BodyTemplate::Lines(_) => None };
        let _ = build_request(&opts, &sample_url, sample_body.as_deref())?;
    }

    // Output writer
    let stdout_is_tty = std::io::stdout().is_terminal();
    let mut writer: Box<dyn Write> = if let Some(path) = &opts.output {
        Box::new(std::fs::File::create(path).map_err(|e| e.to_string())?)
    } else { Box::new(std::io::stdout()) };

    let client_cfg = Arc::new(ClientConfig {
        connect_timeout: opts.connect_timeout,
        tls: tls_config,
        proxy: opts.proxy.as_ref().map(|u| proxy_config(u)),
        unix_socket: opts.unix_socket.clone(),
        connect_to: opts.connect_to.clone(),
        ipv4_only: opts.ipv4 && !opts.ipv6,
        ipv6_only: opts.ipv6 && !opts.ipv4,
        disable_keepalive: opts.disable_keepalive,
        debug_mode: opts.debug,
    });

    if opts.debug {
        return run_debug(&opts, &url_gen, &body_template, client_cfg, &mut writer);
    }

    // Work
    let result = run_work(&opts, &url_gen, &body_template, client_cfg, stdout_is_tty);
    let (successes, errors_btree, total_duration, global_start) = match result { Ok(r) => r, Err(e) => return Err(e) };
    // print result
    let output_is_stdout = opts.output.is_none();
    let style = compute_style(&opts, output_is_stdout && stdout_is_tty);
    let printer = Printer { mode: style, time_unit: opts.time_unit_str.as_deref().and_then(TimeUnitKind::parse), stats_success_breakdown: opts.stats_success_breakdown };
    let mut successes_sorted = successes.clone();
    successes_sorted.sort_by_key(|r| r.start);
    let text = match opts.output_format.as_str() {
        "json" => printer.print_json(&successes_sorted, &errors_btree, total_duration, global_start),
        "csv" => printer.print_csv(&successes_sorted, global_start),
        "quiet" => String::new(),
        _ => printer.print_text(&successes_sorted, &errors_btree, total_duration, global_start),
    };
    if !text.is_empty() { writer.write_all(text.as_bytes()).map_err(|e| e.to_string())?; writer.flush().map_err(|e| e.to_string())?; }
    // DB
    if let Some(db_url) = &opts.db_url {
        eprintln!("Storing results to {}", db_url);
        let rows: Vec<db::DbRow> = successes_sorted.iter().map(|r| db::DbRow {
            url: r.url_path.clone(),
            start: r.start.duration_since(global_start).as_secs_f64(),
