    Ok(0)
}

fn compute_style(opts: &Opts, stdout_tty: bool) -> StyleMode {
    if opts.no_color { return StyleMode::Plain; }
    if !stdout_tty { return StyleMode::Plain; }
    if opts.output.is_some() { return StyleMode::Plain; }
    if std::env::var_os("NO_COLOR").is_some() { return StyleMode::ColorEnvNoColor; }
    StyleMode::Color
}

fn proxy_config(u: &Url) -> ProxyConfig {
    let scheme = u.scheme().to_string();
    let host = u.host_str().unwrap_or("").to_string();
    let port = u.port_or_known_port().unwrap_or(match scheme.as_str() { "https" => 443, _ => 80 });
    let authority = authority_of(u);
    ProxyConfig { scheme, host, port, authority }
}

fn authority_of(u: &Url) -> String {
    // url::Url::authority is not stable as a public accessor in this context; reconstruct from components.
    // Original uses the authority as written/normalised by url crate (userinfo included).
    let mut s = String::new();
    if !u.username().is_empty() || u.password().is_some() {
        s.push_str(u.username());
        if let Some(p) = u.password() { s.push(':'); s.push_str(p); }
        s.push('@');
    }
    if let Some(h) = u.host_str() {
        // Preserve brackets for IPv6 as in host_str? host_str strips brackets for Domain? For Ip it returns without brackets in url 2? Check by reconstructing via serialization of origin.
        match u.host() { Some(url::Host::Ipv6(ip)) => { s.push('['); s.push_str(&ip.to_string()); s.push(']'); }, _ => s.push_str(h) }
    }
    if let Some(p) = u.port() { s.push(':'); s.push_str(&p.to_string()); }
    s
}

