fn check_versions(opts: &mut Opts) -> Result<(), String> {
    if opts.http2 && opts.http_version_str.is_some() { return Err("--http2 and --http-version are exclusive".to_string()); }
    if let Some(vs) = &opts.http_version_str {
        match Version::parse(vs) { Ok(v) => opts.http_version = v, Err(e) => { if e == "__HTTP3__" { return Err("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.".to_string()); } return Err(e); } }
    } else if opts.http2 { opts.http_version = Version::V2; }
    if opts.proxy_http2 && opts.proxy_http_version_str.is_some() { return Err("--http2 and --http-version are exclusive".to_string()); }
    if let Some(vs) = &opts.proxy_http_version_str {
        match Version::parse(vs) { Ok(v) => opts.proxy_http_version = Some(v), Err(e) => { if e == "__HTTP3__" { return Err("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.".to_string()); } return Err(e); } }
    } else if opts.proxy_http2 { opts.proxy_http_version = Some(Version::V2); }
    Ok(())
}

fn build_body(opts: &Opts) -> Result<(BodyTemplate, Option<String>), String> {
    if let Some(s) = &opts.body_string {
        return Ok((BodyTemplate::Fixed(if s.is_empty() { None } else { Some(s.as_bytes().to_vec()) }), None));
    }
    if let Some(p) = &opts.body_path {
        let content = std::fs::read(p).map_err(|e| e.to_string())?;
        return Ok((BodyTemplate::Fixed(if content.is_empty() { None } else { Some(content) }), None));
    }
    if let Some(p) = &opts.body_path_lines {
        let content = std::fs::read_to_string(p).map_err(|e| e.to_string())?;
        let lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
        return Ok((BodyTemplate::Lines(lines), None));
    }
    if !opts.form.is_empty() {
        let (body, ct) = build_form_body(&opts.form)?;
        return Ok((BodyTemplate::Fixed(if body.is_empty() { None } else { Some(body) }), Some(ct)));
    }
    Ok((BodyTemplate::Fixed(None), None))
}

fn build_form_body(forms: &[String]) -> Result<(Vec<u8>, String), String> {
    let boundary = format!("----formdata-oha-{:032x}", util::Rng::new().next_u128());
    let mut body: Vec<u8> = Vec::new();
    for spec in forms {
        let (name, rest) = spec.split_once('=').ok_or_else(|| format!("Failed to parse form data: {}", spec))?;
        let mut segments = rest.split(';');
        let content_spec = segments.next().unwrap_or("");
        let mut directives: Vec<(&str, &str)> = Vec::new();
        for seg in segments { if let Some((k, v)) = seg.split_once('=') { directives.push((k, v)); } }
        let mut content: Vec<u8>;
        let mut filename: Option<String> = None;
        if let Some(path) = content_spec.strip_prefix('@') {
            if path.is_empty() { return Err(format!("Failed to parse form data: {}", spec)); }
            content = std::fs::read(path).map_err(|_| format!("Failed to parse form data: {}", spec))?;
            filename = Some(PathBuf::from(path).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default());
        } else if let Some(path) = content_spec.strip_prefix('<') {
            if path.is_empty() { return Err(format!("Failed to parse form data: {}", spec)); }
            content = std::fs::read(path).map_err(|_| format!("Failed to parse form data: {}", spec))?;
        } else {
            content = content_spec.as_bytes().to_vec();
        }
        let mut ctype: Option<String> = None;
        for (k, v) in &directives {
            match *k { "type" => ctype = Some(v.to_string()), "filename" => filename = Some(v.to_string()), _ => {} }
        }
        body.extend_from_slice(format!("--{}\r\n", boundary).as_bytes());
        body.extend_from_slice(format!("Content-Disposition: form-data; name=\"{}\"", name).as_bytes());
        if let Some(f) = &filename { body.extend_from_slice(format!("; filename=\"{}\"", f).as_bytes()); }
        body.extend_from_slice(b"\r\n");
        if let Some(ct) = &ctype { body.extend_from_slice(format!("Content-Type: {}\r\n", ct).as_bytes()); }
        body.extend_from_slice(b"\r\n");
        body.extend_from_slice(&content);
        body.extend_from_slice(b"\r\n");
    }
    body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
    let ct = format!("multipart/form-data; boundary={}", boundary);
    Ok((body, ct))
}

fn fake_panic_tls(kind: &str) -> ! {
    let (loc, val) = if kind == "key" { ("src/tls_config.rs:39:76", "NoItemsFound") } else { ("src/tls_config.rs:41:55", "NoCertificatesPresented") };
    eprintln!("\nthread 'main' ({}) panicked at {}:\ncalled `Result::unwrap()` on an `Err` value: {}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", util::gettid(), loc, val);
    std::process::exit(101);
}

fn build_tls_config(opts: &Opts) -> Result<tls::TlsConfig, String> {
    let cacert_content = if let Some(p) = &opts.cacert { Some(std::fs::read(p).map_err(|e| e.to_string())?) } else { None };
    if let (Some(cert), Some(key)) = (&opts.cert, &opts.key) {
        let key_content = std::fs::read(key).map_err(|e| e.to_string())?;
        let cert_content = std::fs::read(cert).map_err(|e| e.to_string())?;
        if !contains_bytes(&key_content, b"PRIVATE KEY-----") { fake_panic_tls("key"); }
        if !contains_bytes(&cert_content, b"-----BEGIN CERTIFICATE-----") { fake_panic_tls("cert"); }
    }
    Ok(tls::TlsConfig { insecure: opts.insecure, cacert_content, cert: opts.cert.as_ref().map(PathBuf::from), key: opts.key.as_ref().map(PathBuf::from) })
}
fn contains_bytes(hay: &[u8], needle: &[u8]) -> bool { hay.windows(needle.len()).any(|w| w == needle) }

fn valid_header_value_runtime(s: &str) -> Result<Vec<u8>, String> {
    parse_header_value_bytes(s)
}

fn build_request(opts: &Opts, url: &Url, body: Option<&[u8]>) -> Result<BuiltRequest, String> {
    // validate auth early (also performed during setup)
    let body_vec: Option<Vec<u8>> = body.map(|b| b.to_vec());
    // Determine effective version and uri
    let target_version = opts.http_version;
    let effective_version = if opts.proxy.is_some() {
        if url.scheme() == "https" { target_version } else { opts.proxy_http_version.unwrap_or(Version::V11) }
    } else { target_version };
    let mut fragmentless = url.clone(); fragmentless.set_fragment(None);
    let path_query = {
        let mut pq = if url.path().is_empty() { "/".to_string() } else { url.path().to_string() };
        if let Some(q) = url.query() { pq.push('?'); pq.push_str(q); }
        pq
    };
    let uri_display = if effective_version == Version::V2 {
        fragmentless.to_string()
    } else if opts.proxy.is_some() && url.scheme() != "https" {
        fragmentless.to_string()
    } else { path_query.clone() };
    // Headers
    let headers = build_headers(opts, url, body_vec.as_deref(), effective_version)?;
    let authority = if let Some(h) = model::headers_get(&headers, "host") { String::from_utf8_lossy(h).to_string() } else { authority_of(url) };
    Ok(BuiltRequest {
        method: if !opts.form.is_empty() && opts.method == "GET" { "POST".to_string() } else { opts.method.clone() },
        uri_display,
        version: effective_version,
        headers,
        body: body_vec,
        authority,
        path_query,
        scheme: url.scheme().to_string(),
        connect_headers: if opts.proxy.is_some() { opts.proxy_headers.clone() } else { Vec::new() },
    })
}

fn build_headers(opts: &Opts, url: &Url, body: Option<&[u8]>, effective_version: Version) -> Result<Vec<HeaderKV>, String> {
    // AWS path
    if opts.aws_sigv4.is_some() {
        return build_headers_aws(opts, url, body, effective_version);
    }
    if let Some(auth) = &opts.basic_auth {
        if !auth.contains(':') { return Err("Parse auth".to_string()); }
    }
    let mut headers: Vec<HeaderKV> = Vec::new();
    model::headers_insert(&mut headers, "accept", b"*/*".to_vec());
    if !opts.disable_compression { model::headers_insert(&mut headers, "accept-encoding", b"gzip, compress, deflate, br".to_vec()); }
    model::headers_insert(&mut headers, "user-agent", b"oha/1.12.1".to_vec());
    if opts.disable_keepalive { model::headers_insert(&mut headers, "connection", b"close".to_vec()); }
    for h in &opts.headers { model::headers_insert(&mut headers, &h.name, h.value.clone()); }
    if opts.proxy.is_some() { for h in &opts.proxy_headers { model::headers_insert(&mut headers, &h.name, h.value.clone()); } }
    if let Some(a) = &opts.accept_header { let v = valid_header_value_runtime(a)?; model::headers_insert(&mut headers, "accept", v); }
    if let Some(ct) = &opts.content_type { let v = valid_header_value_runtime(ct)?; model::headers_insert(&mut headers, "content-type", v); }
    else if let Some(ct) = &opts.form_content_type { model::headers_insert(&mut headers, "content-type", ct.as_bytes().to_vec()); }
    if let Some(auth) = &opts.basic_auth {
        let encoded = base64::engine::general_purpose::STANDARD.encode(auth.as_bytes());
        model::headers_insert(&mut headers, "authorization", format!("Basic {}", encoded).into_bytes());
    }
    if effective_version != Version::V2 {
        let host_val = if let Some(h) = &opts.host { valid_header_value_runtime(h)? } else { authority_of(url).into_bytes() };
        model::headers_insert(&mut headers, "host", host_val);
    } else if let Some(h) = &opts.host { let v = valid_header_value_runtime(h)?; model::headers_insert(&mut headers, "host", v); }
    if let Some(b) = body {
        if model::headers_get(&headers, "content-length").is_none() { headers.push(HeaderKV { name: "content-length".to_string(), value: b.len().to_string().into_bytes() }); }
    }
    Ok(headers)
}

fn build_headers_aws(opts: &Opts, url: &Url, body: Option<&[u8]>, effective_version: Version) -> Result<Vec<HeaderKV>, String> {
    let auth = opts.basic_auth.as_ref().ok_or_else(|| "AWS credentials (--auth) required when using --aws-sigv4".to_string())?;
    let cred_parts: Vec<&str> = auth.split(':').collect();
    if cred_parts.len() != 2 { return Err("Invalid AWS credentials format. Expected access_key:secret_key".to_string()); }
    let (access_key, secret) = (cred_parts[0], cred_parts[1]);
    let sig = opts.aws_sigv4.as_ref().unwrap();
    let param_parts: Vec<&str> = sig.split(':').collect();
    if param_parts.len() != 4 || param_parts[0] != "aws" || param_parts[1] != "amz" { return Err("Invalid AWS signing params format. Expected aws:amz:region:service".to_string()); }
    let region = param_parts[2]; let service = param_parts[3];
    let now_secs = util::now_unix_secs();
    let datetime = util::format_utc_amz(now_secs);
    let date = util::format_utc_date(now_secs);
    let host_only = url.host_str().unwrap_or("").to_string();
    // Signable header set (name -> values)
    let mut sign_headers: Vec<HeaderKV> = Vec::new();
    model::headers_insert(&mut sign_headers, "host", host_only.clone().into_bytes());
    for h in &opts.headers { model::headers_insert(&mut sign_headers, &h.name, h.value.clone()); }
    if opts.proxy.is_some() { for h in &opts.proxy_headers { model::headers_insert(&mut sign_headers, &h.name, h.value.clone()); } }
    if let Some(ct) = &opts.content_type { let v = valid_header_value_runtime(ct)?; model::headers_insert(&mut sign_headers, "content-type", v); }
    else if let Some(ct) = &opts.form_content_type { model::headers_insert(&mut sign_headers, "content-type", ct.as_bytes().to_vec()); }
    if opts.disable_keepalive { model::headers_insert(&mut sign_headers, "connection", b"close".to_vec()); }
    model::headers_insert(&mut sign_headers, "x-amz-date", datetime.clone().into_bytes());
    if let Some(tok) = &opts.aws_session { model::headers_insert(&mut sign_headers, "x-amz-security-token", tok.clone().into_bytes()); }
    let body_bytes = body.unwrap_or(&[]);
    model::headers_insert(&mut sign_headers, "content-length", body_bytes.len().to_string().into_bytes());
    // Canonical request
    let canonical_uri = if url.path().is_empty() { "/".to_string() } else { url.path().to_string() };
    let canonical_query = aws_canonical_query(url.query());
    let mut canon_map: std::collections::BTreeMap<String, Vec<String>> = std::collections::BTreeMap::new();
    for h in &sign_headers { canon_map.entry(h.name.clone()).or_default().push(String::from_utf8_lossy(&h.value).trim().to_string()); }
    let signed_names: Vec<String> = canon_map.keys().cloned().collect();
    let canonical_headers = signed_names.iter().map(|n| { let vals = canon_map[n].iter().map(|v| aws_trim_header_value(v)).collect::<Vec<_>>().join(","); format!("{}:{}", n, vals) }).collect::<Vec<_>>().join("\n") + "\n";
    let signed_headers_str = signed_names.join(";");
    let payload_hash = aws::sha256_hex(body_bytes);
    let method_for_sign = if !opts.form.is_empty() && opts.method == "GET" { "POST" } else { &opts.method };
    let canonical_request = format!("{}\n{}\n{}\n{}\n{}\n{}", method_for_sign, canonical_uri, canonical_query, canonical_headers, signed_headers_str, payload_hash);
    let scope = format!("{}/{}/{}/aws4_request", date, region, service);
    let string_to_sign = format!("AWS4-HMAC-SHA256\n{}\n{}\n{}", datetime, scope, aws::sha256_hex(canonical_request.as_bytes()));
    let k_date = aws::hmac_sha256(format!("AWS4{}", secret).as_bytes(), date.as_bytes());
    let k_region = aws::hmac_sha256(&k_date, region.as_bytes());
    let k_service = aws::hmac_sha256(&k_region, service.as_bytes());
    let k_signing = aws::hmac_sha256(&k_service, b"aws4_request");
    let signature = aws::hex(&aws::hmac_sha256(&k_signing, string_to_sign.as_bytes()));
    let authorization = format!("AWS4-HMAC-SHA256 Credential={}/{},SignedHeaders={},Signature={}", access_key, scope, signed_headers_str, signature);
    // Build final headers in a shape similar to the original
    let mut headers: Vec<HeaderKV> = Vec::new();
    if opts.aws_session.is_some() {
        model::headers_insert(&mut headers, "x-amz-date", datetime.clone().into_bytes());
        model::headers_insert(&mut headers, "host", host_only.clone().into_bytes());
        if let Some(tok) = &opts.aws_session { model::headers_insert(&mut headers, "x-amz-security-token", tok.clone().into_bytes()); }
        for h in &sign_headers { if h.name != "x-amz-date" && h.name != "host" && h.name != "x-amz-security-token" { model::headers_insert(&mut headers, &h.name, h.value.clone()); } }
    } else {
        // host, custom, date, then remaining sign headers
        model::headers_insert(&mut headers, "host", host_only.clone().into_bytes());
        for h in &opts.headers { model::headers_insert(&mut headers, &h.name, h.value.clone()); }
        if opts.proxy.is_some() { for h in &opts.proxy_headers { model::headers_insert(&mut headers, &h.name, h.value.clone()); } }
        model::headers_insert(&mut headers, "x-amz-date", datetime.clone().into_bytes());
        for h in &sign_headers { if !["host", "x-amz-date"].contains(&h.name.as_str()) && opts.headers.iter().all(|x| x.name != h.name) { model::headers_insert(&mut headers, &h.name, h.value.clone()); } }
        // Ensure content-type and content-length present in that order
        // (headers_insert above already handled)
    }
    // Add defaults if not already present
    if model::headers_get(&headers, "accept").is_none() { headers.push(HeaderKV { name: "accept".into(), value: b"*/*".to_vec() }); }
    if !opts.disable_compression && model::headers_get(&headers, "accept-encoding").is_none() { headers.push(HeaderKV { name: "accept-encoding".into(), value: b"gzip, compress, deflate, br".to_vec() }); }
    if model::headers_get(&headers, "user-agent").is_none() { headers.push(HeaderKV { name: "user-agent".into(), value: b"oha/1.12.1".to_vec() }); }
    if let Some(a) = &opts.accept_header { let v = valid_header_value_runtime(a)?; model::headers_insert(&mut headers, "accept", v); }
    model::headers_insert(&mut headers, "authorization", authorization.into_bytes());
    let _ = effective_version;
    Ok(headers)
}

fn aws_trim_header_value(v: &str) -> String {
    let mut out = String::new(); let mut last_space = false;
    for ch in v.trim().chars() { if ch == ' ' || ch == '\t' { if !last_space { out.push(' '); last_space = true; } } else { out.push(ch); last_space = false; } }
    out
}
fn aws_canonical_query(query: Option<&str>) -> String {
    let q = match query { None => return String::new(), Some(q) if q.is_empty() => return String::new(), Some(q) => q };
    let mut pairs: Vec<(String, String)> = Vec::new();
    for part in q.split('&') {
        let (k, v) = match part.split_once('=') { Some((k, v)) => (k.to_string(), v.to_string()), None => (part.to_string(), String::new()) };
        pairs.push((aws_uri_encode(&k), aws_uri_encode(&v)));
    }
    pairs.sort();
    pairs.iter().map(|(k, v)| format!("{}={}", k, v)).collect::<Vec<_>>().join("&")
}
fn aws_uri_encode(s: &str) -> String {
    let mut out = String::new();
    let bytes = s.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'%' && i + 2 < bytes.len() && bytes[i+1].is_ascii_hexdigit() && bytes[i+2].is_ascii_hexdigit() { out.push('%'); out.push(bytes[i+1] as char); out.push(bytes[i+2] as char); i += 3; continue; }
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') { out.push(b as char); } else { out.push_str(&format!("%{:02X}", b)); }
        i += 1;
    }
    out
}

fn run_debug(opts: &Opts, url_gen: &UrlGenerator, body_template: &BodyTemplate, client_cfg: Arc<ClientConfig>, writer: &mut Box<dyn Write>) -> Result<i32, String> {
    let url = url_gen.generate()?;
    let body: Option<Vec<u8>> = match body_template { BodyTemplate::Fixed(b) => b.clone(), BodyTemplate::Lines(lines) => { if lines.is_empty() { None } else { let mut rng = util::Rng::new(); let line = &lines[rng.below(lines.len())]; if line.is_empty() { None } else { Some(line.as_bytes().to_vec()) } } } };
    let built = build_request(opts, &url, body.as_deref())?;
    // DNS pre-check (unless unix socket non-https)
    if !(opts.unix_socket.is_some() && url.scheme() != "https") {
        let (host_raw, port_raw) = (url.host_str().unwrap_or("").to_string(), WorkerClient::url_port_pub(&url));
        // connect-to override
        let mut host = host_raw.clone(); let mut port = port_raw;
        if let Some(e) = opts.connect_to.iter().find(|e| e.requested_host == host_raw && e.requested_port == port_raw) { host = e.target_host.clone(); port = e.target_port; }
        client::resolve_host(&host, port, opts.ipv4 && !opts.ipv6, opts.ipv6 && !opts.ipv4)?;
    }
    // Print request
    writer.write_all(format_debug_request(&built).as_bytes()).map_err(|e| e.to_string())?;
    writer.flush().map_err(|e| e.to_string())?;
    let mut client = WorkerClient::new(client_cfg);
    let ctx = ReqCtx { request_deadline: opts.timeout.map(|t| Instant::now() + t), abort_deadline: None, collect_body: true };
    let outcome = client.send_once(&url, &built, &ctx).map_err(|e| e)?;
    writer.write_all(format_debug_response(&outcome.response).as_bytes()).map_err(|e| e.to_string())?;
    writer.flush().map_err(|e| e.to_string())?;
    Ok(0)
}

pub fn format_debug_request(built: &BuiltRequest) -> String {
    let mut out = String::new();
    out.push_str("Request {\n");
    out.push_str(&format!("    method: {},\n", built.method));
    out.push_str(&format!("    uri: {},\n", built.uri_display));
    out.push_str(&format!("    version: {},\n", built.version.label()));
    out.push_str("    headers: {\n");
    for h in &built.headers { out.push_str(&format!("        \"{}\": {},\n", h.name, util::escape_header_value_debug(&h.value))); }
    out.push_str("    },\n");
    out.push_str("    body: Full {\n");
    match &built.body {
        None => out.push_str("        data: None,\n"),
        Some(b) => out.push_str(&format!("        data: Some(\n            {},\n        ),\n", util::escape_byte_string(b))),
    }
    out.push_str("    },\n");
    out.push_str("}\n");
    out
}
pub fn format_debug_response(resp: &client::ResponseData) -> String {
    let mut out = String::new();
    out.push_str("Response {\n");
    out.push_str(&format!("    status: {},\n", resp.status));
    out.push_str(&format!("    version: {},\n", resp.version_label));
    out.push_str("    headers: {\n");
    for h in &resp.headers { out.push_str(&format!("        \"{}\": {},\n", h.name, util::escape_header_value_debug(&h.value))); }
    out.push_str("    },\n");
    out.push_str(&format!("    body: {},\n", util::escape_byte_string(&resp.body)));
    out.push_str("}\n");
    out
}

// ---------- work ----------
struct MonitorData {
    ends: Vec<(Instant, Duration, usize)>,
    status: BTreeMap<u16, usize>,
    errors: Vec<(String, usize)>,
    attempts: usize,
}
impl MonitorData { fn new() -> Self { MonitorData { ends: Vec::new(), status: BTreeMap::new(), errors: Vec::new(), attempts: 0 } } }

struct SharedWork {
    opts: Arc<Opts>,
    url_gen: Arc<UrlGenerator>,
    body_template: Arc<BodyTemplate>,
    client_cfg: Arc<ClientConfig>,
    global_start: Instant,
    deadline: Option<Instant>,
    next_idx: AtomicUsize,
    rate: Option<RateLimiter>,
    results: Mutex<Vec<model::SuccessResult>>,
    errors: Mutex<BTreeMap<String, usize>>,
    monitor: Mutex<MonitorData>,
}

struct RateLimiter {
    kind: RateKind,
    start: Instant,
    counter: AtomicUsize,
    latency_correction: bool,
}
enum RateKind { Qps(f64), Burst { delay: Duration, rate: usize } }
enum RateOutcome { Proceed(Option<Instant>), Aborted }
impl RateLimiter {
    fn acquire(&self, abort_deadline: Option<Instant>, wait_ongoing: bool) -> RateOutcome {
        let idx = self.counter.fetch_add(1, Ordering::SeqCst);
        let scheduled = match &self.kind {
            RateKind::Qps(q) => {
                if *q == 0.0 { return RateOutcome::Proceed(None); }
                if q.is_infinite() { self.start } else {
                    match self.start.checked_add(Duration::from_secs_f64(idx as f64 / q)) { Some(t) => t, None => self.start }
                }
            }
            RateKind::Burst { delay, rate } => {
                let group = (idx / (*rate).max(1)) as u32;
                let mult = delay.checked_mul(group + 1).unwrap_or(Duration::from_secs(0));
                match self.start.checked_add(mult) { Some(t) => t, None => self.start }
            }
        };
        loop {
            let now = Instant::now();
            if now >= scheduled { break; }
            if client::INTERRUPTED.load(Ordering::SeqCst) { return RateOutcome::Aborted; }
            if !wait_ongoing { if let Some(d) = abort_deadline { if now >= d { return RateOutcome::Aborted; } } }
            let remain = scheduled.duration_since(now);
            std::thread::sleep(remain.min(Duration::from_millis(5)));
        }
        if self.latency_correction { RateOutcome::Proceed(None) } else { RateOutcome::Proceed(Some(scheduled)) }
    }
}

fn run_work(opts: &Opts, url_gen: &UrlGenerator, body_template: &BodyTemplate, client_cfg: Arc<ClientConfig>, stdout_is_tty: bool) -> Result<(Vec<model::SuccessResult>, BTreeMap<String, usize>, Duration, Instant), String> {
    // Pre-lookup
    let global_start = Instant::now();
    if !opts.no_pre_lookup {
        if !(opts.unix_socket.is_some() && {
            // peek scheme of a generated URL; generating again is cheap
            let u = url_gen.generate()?; u.scheme() != "https"
        }) {
            let sample = url_gen.generate()?;
            let host_raw = sample.host_str().unwrap_or("").to_string();
            let port_raw = WorkerClient::url_port_pub(&sample);
            let mut host = host_raw.clone(); let mut port = port_raw;
            if let Some(e) = opts.connect_to.iter().find(|e| e.requested_host == host_raw && e.requested_port == port_raw) { host = e.target_host.clone(); port = e.target_port; }
            client::resolve_host(&host, port, opts.ipv4 && !opts.ipv6, opts.ipv6 && !opts.ipv4)?;
        }
    }
    // rate limiter panics for bad q in main thread (matching original behaviour)
    if let Some(q) = opts.query_per_second {
        if q.is_nan() && (opts.duration.is_some() || opts.n_requests > 0) { let _ = util::duration_from_secs_f64_panic(1.0 / q); }
        if q < 0.0 && (opts.duration.is_some() || opts.n_requests > 1) { let _ = util::duration_from_secs_f64_panic(1.0 / q); }
    }
    client::install_signal_handler();
    let deadline = opts.duration.map(|d| global_start + d);
    let rate = make_rate_limiter(opts, global_start);
    let shared = Arc::new(SharedWork {
        opts: Arc::new(opts.clone()),
        url_gen: Arc::new(url_gen.try_clone_for_work()),
        body_template: Arc::new(body_template.clone()),
        client_cfg,
        global_start,
        deadline,
        next_idx: AtomicUsize::new(0),
        rate,
        results: Mutex::new(Vec::new()),
        errors: Mutex::new(BTreeMap::new()),
        monitor: Mutex::new(MonitorData::new()),
    });
    let use_tui = !opts.no_tui && stdout_is_tty && !opts.debug;
    let n_workers = if shared.opts.http_version == Version::V2 { shared.opts.n_connections * shared.opts.n_http2_parallel } else { shared.opts.n_connections };
    // TUI setup
    let mut tui = if use_tui { Some(tui::Tui::start(shared.clone())) } else { None };
    let mut handles = Vec::new();
    for _ in 0..n_workers {
        let sh = shared.clone();
        handles.push(std::thread::spawn(move || worker_loop(sh)));
    }
    for h in handles { let _ = h.join(); }
    if let Some(t) = &mut tui { t.stop(); }
    let total_duration = global_start.elapsed();
    let results = shared.results.lock().unwrap().clone();
    let errors = shared.errors.lock().unwrap().clone();
    Ok((results, errors, total_duration, global_start))
}

fn make_rate_limiter(opts: &Opts, start: Instant) -> Option<RateLimiter> {
    if let Some(q) = opts.query_per_second {
        return Some(RateLimiter { kind: RateKind::Qps(q), start, counter: AtomicUsize::new(0), latency_correction: opts.latency_correction });
    }
    if let Some(delay) = opts.burst_delay {
        return Some(RateLimiter { kind: RateKind::Burst { delay, rate: opts.burst_rate.unwrap_or(1) }, start, counter: AtomicUsize::new(0), latency_correction: opts.latency_correction });
    }
    None
}

fn worker_loop(shared: Arc<SharedWork>) {
    let mut client = WorkerClient::new(shared.client_cfg.clone());
    let mut rng = util::Rng::new();
    loop {
        if client::INTERRUPTED.load(Ordering::SeqCst) { break; }
        let is_duration = shared.opts.duration.is_some();
        if is_duration {
            if let Some(d) = shared.deadline { if Instant::now() >= d { break; } }
        } else {
            let idx = shared.next_idx.fetch_add(1, Ordering::SeqCst);
            if idx >= shared.opts.n_requests { break; }
        }
        // rate limit
        let mut correction: Option<Instant> = None;
        if let Some(rate) = &shared.rate {
            match rate.acquire(shared.deadline, shared.opts.wait_ongoing) {
                RateOutcome::Proceed(c) => correction = c,
                RateOutcome::Aborted => { record_error(&shared, client::ERR_ABORTED.to_string()); break; }
            }
        }
        let url = match shared.url_gen.generate() { Ok(u) => u, Err(e) => { record_error(&shared, e); if is_duration { continue; } else { continue; } } };
        let body: Option<Vec<u8>> = match &*shared.body_template {
            BodyTemplate::Fixed(b) => b.clone(),
            BodyTemplate::Lines(lines) => { if lines.is_empty() { None } else { let line = &lines[rng.below(lines.len())]; if line.is_empty() { None } else { Some(line.as_bytes().to_vec()) } } }
        };
        let built = match build_request(&shared.opts, &url, body.as_deref()) { Ok(b) => b, Err(e) => { record_error(&shared, e); continue; } };
        let start = Instant::now();
        let ctx = ReqCtx {
            request_deadline: shared.opts.timeout.map(|t| start + t),
            abort_deadline: if is_duration && !shared.opts.wait_ongoing { shared.deadline } else { None },
            collect_body: false,
        };
        let outcome = execute_with_redirects(&mut client, &shared.opts, url.clone(), built, body.clone(), &ctx);
        match outcome {
            Ok((resp, dns_info, _final_url)) => {
                let end = Instant::now();
                let duration = end.duration_since(correction.unwrap_or(start));
                let result = model::SuccessResult {
                    start, end, start_correction: correction, first_byte: resp.first_byte, status: resp.status, len_bytes: resp.body_len,
                    dns_lookup: dns_info.map(|d| d.0), dns_dialup: dns_info.map(|d| d.1), duration, url_path: path_query_of(&url),
                };
                shared.results.lock().unwrap().push(result.clone());
                let mut mon = shared.monitor.lock().unwrap();
                mon.attempts += 1;
                mon.ends.push((end, result.duration, result.len_bytes));
                *mon.status.entry(result.status).or_insert(0) += 1;
            }
            Err(e) => { record_error(&shared, e); }
        }
        if client::INTERRUPTED.load(Ordering::SeqCst) { break; }
    }
}

fn path_query_of(url: &Url) -> String {
    let mut pq = if url.path().is_empty() { "/".to_string() } else { url.path().to_string() };
    if let Some(q) = url.query() { pq.push('?'); pq.push_str(q); }
    pq
}

fn record_error(shared: &Arc<SharedWork>, msg: String) {
    { let mut errs = shared.errors.lock().unwrap(); *errs.entry(msg.clone()).or_insert(0) += 1; }
    let mut mon = shared.monitor.lock().unwrap();
    mon.attempts += 1;
    if let Some(entry) = mon.errors.iter_mut().find(|(m, _)| *m == msg) { entry.1 += 1; } else { mon.errors.push((msg, 1)); }
}

fn execute_with_redirects(client: &mut WorkerClient, opts: &Opts, mut url: Url, mut built: BuiltRequest, body: Option<Vec<u8>>, ctx: &ReqCtx) -> Result<(client::ResponseData, Option<(Duration, Duration)>, Url), String> {
    let mut redirect_count = 0usize;
    let mut dns_result: Option<(Duration, Duration)> = None;
    loop {
        let outcome = client.send_once(&url, &built, ctx)?;
        if dns_result.is_none() { dns_result = outcome.dns_info; }
        let resp = outcome.response;
        let is_redirect = (300..400).contains(&resp.status);
        if is_redirect && opts.redirect > 0 {
            if let Some(loc) = model::headers_get(&resp.headers, "location") {
                if redirect_count >= opts.redirect { return Err("Redirection limit has reached".to_string()); }
                redirect_count += 1;
                let loc_str = String::from_utf8_lossy(loc).to_string();
                let next_url = url.join(&loc_str).map_err(|e| e.to_string())?;
                url = next_url;
                built = build_request(opts, &url, body.as_deref())?;
                continue;
            }
        }
        return Ok((resp, dns_result, url));
    }
}

// Allow SharedWork generic access from tui module
impl SharedWork {
    pub fn monitor_snapshot(&self) -> (Vec<(Instant, Duration, usize)>, BTreeMap<u16, usize>, Vec<(String, usize)>, usize) {
        let mon = self.monitor.lock().unwrap();
        (mon.ends.clone(), mon.status.clone(), mon.errors.clone(), mon.attempts)
    }
}
