fn fg(code: u8, enabled: bool) -> String { if enabled { format!("\x1b[38;5;{}m", code) } else { String::new() } }
fn reset(enabled: bool) -> String { if enabled { "\x1b[39m".to_string() } else { String::new() } }

fn draw_frame(shared: &Arc<SharedWork>) {
    let (cols, rows) = term_size();
    if cols < 10 || rows < 5 { return; }
    let color = !shared.opts.no_color;
