use crate::{SharedWork, util};
use std::io::{Read, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

pub struct Tui {
    stop: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
    original_termios: Option<libc::termios>,
}

impl Tui {
    pub fn start(shared: Arc<SharedWork>) -> Self {
        let original_termios = enable_raw_mode();
        {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(b"\x1b[?1049h\x1b[?25l");
            let _ = out.flush();
        }
        // input thread (detached)
        {
            std::thread::spawn(move || {
                let stdin = std::io::stdin();
                let mut lock = stdin.lock();
                let mut buf = [0u8; 64];
                loop {
                    match lock.read(&mut buf) {
                        Ok(0) => break,
                        Ok(n) => {
                            for &b in &buf[..n] {
                                if b == b'q' || b == 3 { crate::client::INTERRUPTED.store(true, Ordering::SeqCst); }
                            }
                        }
                        Err(_) => break,
                    }
                }
            });
        }
        let stop = Arc::new(AtomicBool::new(false));
        let stop_clone = stop.clone();
        let fps = shared.opts.fps;
        let handle = std::thread::spawn(move || {
            let interval = if fps == 0 { Duration::from_secs(1) } else { Duration::from_secs_f64(1.0 / fps as f64) };
            while !stop_clone.load(Ordering::SeqCst) {
                draw_frame(&shared);
                std::thread::sleep(interval);
            }
        });
        Tui { stop, handle: Some(handle), original_termios }
    }
    pub fn stop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(h) = self.handle.take() { let _ = h.join(); }
        {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(b"\x1b[39m\x1b[49m\x1b[0m\x1b[?25l\x1b[?25h\x1b[?1049l");
            let _ = out.flush();
        }
        if let Some(orig) = self.original_termios { unsafe { libc::tcsetattr(0, libc::TCSANOW, &orig); } }
    }
}

fn enable_raw_mode() -> Option<libc::termios> {
    unsafe {
        let mut orig: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(0, &mut orig) != 0 { return None; }
        let mut raw = orig;
        libc::cfmakeraw(&mut raw);
        if libc::tcsetattr(0, libc::TCSANOW, &raw) != 0 { return None; }
        Some(orig)
    }
}

fn term_size() -> (usize, usize) {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(1, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0 { return (ws.ws_col as usize, ws.ws_row as usize); }
    }
    (80, 24)
}

fn fg(code: u8, enabled: bool) -> String { if enabled { format!("\x1b[38;5;{}m", code) } else { String::new() } }
fn reset(enabled: bool) -> String { if enabled { "\x1b[39m".to_string() } else { String::new() } }

fn draw_frame(shared: &Arc<SharedWork>) {
    let (cols, rows) = term_size();
    if cols < 10 || rows < 5 { return; }
    let color = !shared.opts.no_color;
    let (ends, status, errors, attempts) = shared.monitor_snapshot();
    let now = Instant::now();
    let elapsed = now.duration_since(shared.global_start);
    let mut lines: Vec<String> = Vec::new();
    // Progress
    lines.push(block_top(cols, "Progress", None, color));
    let inner = cols.saturating_sub(2);
    let (ratio, label) = if let Some(dur) = shared.opts.duration {
        let r = if dur.as_secs_f64() > 0.0 { (elapsed.as_secs_f64() / dur.as_secs_f64()).min(1.0) } else { 1.0 };
        (r, format!("{}s / {}s", elapsed.as_secs(), dur.as_secs()))
    } else {
        let total = shared.opts.n_requests;
        let r = if total > 0 { attempts as f64 / total as f64 } else { 0.0 };
        (r.min(1.0), format!("{} / {}", attempts, total))
    };
    let mut content_chars: Vec<char> = vec![' '; inner];
    let filled = (ratio * inner as f64) as usize;
    for i in 0..filled.min(inner) { content_chars[i] = '█'; }
    let label_start = inner.saturating_sub(label.len()) / 2;
    for (i, ch) in label.chars().enumerate() { if label_start + i < inner { content_chars[label_start+i] = ch; } }
    let content: String = content_chars.iter().collect();
    lines.push(format!("│{}{}{}│", fg(6, color), content, reset(color)));
    lines.push(block_bottom(cols, None, color));
    // Stats / status
    let left_w = cols / 2;
    let right_w = cols - left_w;
    let unit_label = if elapsed.as_secs() < 1 { "ms" } else { "sec" };
    lines.push(format!("{}{}", block_top(left_w, &format!("Stats for last {}", unit_label), None, color), block_top(right_w, "Status code distribution", None, color)));
    // last second stats
    let window_start = now - Duration::from_secs(1);
    let recent: Vec<&(Instant, Duration, usize)> = ends.iter().filter(|(end, _, _)| *end >= window_start && *end <= now).collect();
    let req_count = recent.len();
    let data_sum: usize = recent.iter().map(|(_, _, n)| *n).sum();
    let mut durations: Vec<f64> = recent.iter().map(|(_, d, _)| d.as_secs_f64()).collect();
    durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let average = if durations.is_empty() { f64::NAN } else { durations.iter().sum::<f64>() / durations.len() as f64 };
    let mut stat_lines: Vec<(String, Option<u8>)> = vec![
        (format!("Requests : {}", req_count), None),
        (format!("Slowest: {:.4} secs", slowest), Some(3)),
        (format!("Fastest: {:.4} secs", fastest), Some(2)),
        (format!("Average: {:.4} secs", average), Some(6)),
        (format!("Data: {}", crate::printer::format_bytes(data_sum as f64)), None),
        (format!("Number of open files: {} / {}", count_open_files(), open_file_limit()), None),
    ];
    let mut status_lines: Vec<String> = status.iter().map(|(code, cnt)| format!("[{}] {} responses", code, cnt)).collect();
    let mid_rows = 6usize;
    for i in 0..mid_rows {
        let ltext = stat_lines.get(i).map(|(s, _)| s.clone()).unwrap_or_default();
        let lcolor = stat_lines.get(i).and_then(|(_, c)| *c);
        let rtext = status_lines.get(i).cloned().unwrap_or_default();
        let left_content = pad_str(&ltext, left_w.saturating_sub(2));
        let left_rendered = match lcolor { Some(c) => format!("{}{}{}", fg(c, color), left_content, reset(color)), None => left_content };
        let right_content = pad_str(&rtext, right_w.saturating_sub(2));
        lines.push(format!("│{}││{}│", left_rendered, right_content));
    }
    lines.push(format!("{}{}", block_bottom(left_w, None, color), block_bottom(right_w, None, color)));
    // Error distribution
    lines.push(block_top(cols, "Error distribution", None, color));
    for (msg, cnt) in &errors { lines.push(format!("│{}│", pad_str(&format!("[{}] {}", cnt, msg), inner))); }
    lines.push(block_bottom(cols, None, color));
    // Graphs
    let used = lines.len();
    let graph_h = rows.saturating_sub(used);
    if graph_h >= 4 {
        let graph_inner_h = graph_h.saturating_sub(2);
        // Build request bins
        let (req_bins, req_labels) = request_bins(shared, &ends, elapsed);
        let (resp_bins, resp_labels) = response_bins(&ends);
        lines.push(format!("{}{}", block_top(left_w, &format!("Requests / past {} (auto). press -/+/a to change", unit_label), Some(2), color), block_top(right_w, "Response time histogram", Some(3), color)));
        let bar_rows = graph_inner_h.saturating_sub(1).max(1);
        let left_bars = render_bars(&req_bins, left_w.saturating_sub(2), bar_rows, 2, color);
        let right_bars = render_bars(&resp_bins, right_w.saturating_sub(2), bar_rows, 3, color);
        for i in 0..bar_rows { lines.push(format!("{}{}", left_bars.get(i).cloned().unwrap_or_default(), right_bars.get(i).cloned().unwrap_or_default())); }
        lines.push(format!("│{}││{}│", pad_str(&req_labels, left_w.saturating_sub(2)), pad_str(&resp_labels, right_w.saturating_sub(2))));
        lines.push(format!("{}{}", block_bottom(left_w, Some(2), color), block_bottom(right_w, Some(3), color)));
    }
    // Clip to rows
    lines.truncate(rows);
    let mut out = String::new();
    out.push_str("\x1b[H");
    out.push_str(&lines.join("\r\n"));
    let mut stdout = std::io::stdout().lock();
    let _ = stdout.write_all(out.as_bytes());
    let _ = stdout.flush();
    let _ = &mut stat_lines; let _ = &mut status_lines;
}

fn count_open_files() -> usize { std::fs::read_dir("/proc/self/fd").map(|d| d.count()).unwrap_or(0) }
fn open_file_limit() -> String {
    if let Ok(content) = std::fs::read_to_string("/proc/self/limits") {
        for line in content.lines() { if line.starts_with("Max open files") { let parts: Vec<&str> = line.split_whitespace().collect(); if parts.len() >= 4 { return parts[3].to_string(); } } }
    }
    "1024".to_string()
}

fn block_top(w: usize, title: &str, color_code: Option<u8>, color: bool) -> String {
    if w < 2 { return String::new(); }
    let pre = match color_code { Some(c) => fg(c, color), None => String::new() };
    let post = match color_code { Some(_) => reset(color), _ => String::new() };
    let inner_title = format!("┌{}", title);
    let mut s = inner_title;
    let cur = s.chars().count();
    if cur < w { s.push_str(&"─".repeat(w - cur - 1)); }
    s.push('┐');
    // truncate/pad to width
    format!("{}{}{}", pre, truncate_str(&s, w), post)
}
fn block_bottom(w: usize, color_code: Option<u8>, color: bool) -> String {
    if w < 2 { return String::new(); }
    let pre = match color_code { Some(c) => fg(c, color), None => String::new() };
    let post = match color_code { Some(_) => reset(color), _ => String::new() };
    format!("{}└{}┘{}", pre, "─".repeat(w-2), post)
}
fn pad_str(s: &str, w: usize) -> String { let t = truncate_str(s, w); let len = t.chars().count(); if len < w { format!("{}{}", t, " ".repeat(w - len)) } else { t } }
fn truncate_str(s: &str, w: usize) -> String { s.chars().take(w).collect() }

fn request_bins(shared: &Arc<SharedWork>, ends: &[(Instant, Duration, usize)], elapsed: Duration) -> (Vec<usize>, String) {
    let total_secs = if let Some(d) = shared.opts.duration { d.as_secs() as usize } else { elapsed.as_secs() as usize };
    let nbins = total_secs + 1;
    let mut bins = vec![0usize; nbins.max(1)];
    for (end, _, _) in ends { let sec = end.duration_since(shared.global_start).as_secs() as usize; if sec < bins.len() { bins[sec] += 1; } else if let Some(last) = bins.last_mut() { *last += 1; } }
    // labels
    let col_label = bins.iter().enumerate().map(|(i, _)| format!("{}s", i)).collect::<Vec<_>>().join(" ");
    (bins, col_label)
}
fn response_bins(ends: &[(Instant, Duration, usize)]) -> (Vec<usize>, String) {
    let mut durs: Vec<f64> = ends.iter().map(|(_, d, _)| d.as_secs_f64()).collect();
    if durs.is_empty() { return (vec![0;7], String::new()); }
    durs.sort_by(|a,b| a.partial_cmp(b).unwrap());
    let min = durs[0]; let max = *durs.last().unwrap();
    let step = (max - min) / 6.0;
    let mut bins = vec![0usize; 7];
    for &d in &durs { let idx = if max > min { (((d - min) / (max - min)) * 6.0).ceil() as usize } else { 0 }; bins[idx.min(6)] += 1; }
    let labels = (0..7).map(|i| format!("{:.4}", min + step * i as f64)).collect::<Vec<_>>().join(" ");
    (bins, labels)
}

fn render_bars(values: &[usize], inner_w: usize, rows: usize, color_code: u8, color: bool) -> Vec<String> {
    let n = values.len().max(1);
    let col_w = ((inner_w + 1) / n).saturating_sub(1).clamp(1, 7);
    let maxv = *values.iter().max().unwrap_or(&0);
    let mut lines: Vec<String> = Vec::new();
    for row in 0..rows {
        let level_from_bottom = rows - row; // 1-indexed
        let mut line = String::from("│");
        for (i, &v) in values.iter().enumerate() {
            let mut cells: Vec<char> = vec![' '; col_w];
            if maxv > 0 && v > 0 {
                let total_eighths = ((v as f64 / maxv as f64) * (rows as f64) * 8.0).round() as usize;
                let full = total_eighths / 8; let frac = total_eighths % 8;
                let my_full_below = if level_from_bottom <= full { true } else { false };
                if my_full_below {
                    for c in cells.iter_mut() { *c = '█'; }
                    if level_from_bottom == full + 0 && frac == 0 { /* already full */ }
                } else if level_from_bottom == full + 1 && frac > 0 {
                    let ch = ['▁','▂','▃','▄','▅','▆','▇','█'][(frac-1).min(7)];
                    for c in cells.iter_mut() { *c = ch; }
                }
                // value overlay on bottom row
                if row == rows - 1 {
                    let vs = v.to_string();
                    let start = col_w.saturating_sub(vs.len()) / 2;
                    for (j, ch) in vs.chars().enumerate() { if start + j < col_w { cells[start+j] = ch; } }
                }
            }
            line.push_str(&format!("{}{}{}", fg(color_code, color), cells.iter().collect::<String>(), reset(color)));
            if i + 1 < values.len() { line.push(' '); }
        }
        // pad
        let display_len = 1 + values.len() * (col_w + 1) - 1;
        if display_len < inner_w + 1 { line.push_str(&" ".repeat(inner_w + 1 - display_len)); }
        line.push('│');
        lines.push(line);
    }
    lines
}
